const MITRE={"T1078":{"name":"Valid Accounts","tactic":"Initial Access","summary":"Anomalous logon patterns, abnormal logon types, geographic or time-based anomalies, and privileged use that doesn't match the account's normal profile.","detect":["Successful/remote logons from unusual geo, time window, device, or logon type","Service or admin account use outside expected hosts, schedules, or parent-process patterns","Cloud sign-ins from impossible travel, risky IPs, or repeated MFA prompts","API use exceeding the account's normal scope"],"pivots":["account","source IP","logon type","user agent","role change"],"mits":["M1032","M1026","M1018","M1036","M1047"],"start":{"win":"Start with 4624 and 4625, then test whether 4672 or 4688 appears in the same session.","aws":"Start with ConsoleLogin or AssumeRole, then check for CreateAccessKey or AttachRolePolicy."},"ref":false,"subs":4},"T1059":{"name":"Command & Scripting Interpreter","tactic":"Execution","summary":"Interpreters launched in abnormal contexts, encoded/obfuscated arguments, and chaining to second-stage execution or network activity.","detect":["powershell/cmd/wscript/mshta outside expected admin context","Encoded, obfuscated, or unusually long command lines","Suspicious parent lineage — Office, browser, or web-service processes","Cloud CLI actions chained to auth-context shifts"],"pivots":["process name","command line","parent process","child process"],"mits":["M1038","M1042","M1045","M1040","M1021"],"start":{"win":"Start with 4688 filtering for script interpreters, then pivot on the adjacent logon session.","aws":"High-risk CLI activity after ConsoleLogin or AssumeRole when API scope widens."},"ref":false,"subs":13},"T1021":{"name":"Remote Services","tactic":"Lateral Movement","summary":"A behaviour chain: remote logon first, then uncommon command execution, file manipulation, privilege escalation, or new connections from that session.","detect":["RDP/SMB/WMI/SSH logon from a new source or uncommon account","Remote session followed by command execution or file transfer","Service-account remote use outside standard management paths"],"pivots":["logon type","source IP","destination host","session ID","follow-on process"],"mits":["M1035","M1030","M1032","M1042","M1026"],"start":{"win":"Start with 4624 logon types 3 or 10, then inspect 4688 and 7045 in the same session.","aws":"Identity and control-plane events reveal which cloud account enabled the remote path."},"ref":false,"subs":8},"T1110":{"name":"Brute Force","tactic":"Credential Access","summary":"Repeated failures, password spraying across many accounts, and a suspicious success from the same source, user, or timeframe.","detect":["High-volume failed attempts in a short interval","Many accounts from one IP — spray pattern","Failures followed by success from the same source","Excessive cloud login attempts that later become valid sessions"],"pivots":["source IP","target account","failure code","success-after-fail"],"mits":["M1032","M1036","M1027","M1018"],"start":{"win":"Start with 4625 bursts, then check for a 4624 success from the same source.","aws":"ConsoleLogin failures, then test for a later success from the same IP or region."},"ref":false,"subs":4},"T1136":{"name":"Create Account","tactic":"Persistence","summary":"Unexpected account creation, accounts created by non-provisioning identities, and accounts immediately given privileged access.","detect":["New account created by a non-admin or unexpected process","Account created and immediately added to privileged groups","Username mimicking a service or built-in account","Cloud IAM user via CLI from unexpected IP, immediately given admin"],"pivots":["new account","creating user","creating process","group membership"],"mits":["M1032","M1026","M1030","M1018"],"start":{"win":"Start with 4720 and test for 4732 immediately after in the same session.","aws":"Start with CreateUser, then CreateAccessKey and AttachRolePolicy in the same session."},"ref":false,"subs":3},"T1543.003":{"name":"Windows Service","tactic":"Persistence","summary":"Services installed by unexpected processes, from suspicious paths, or running as SYSTEM without a corresponding deployment.","detect":["New service outside a known deployment or change window","Binary path in temp, appdata, or a random-named location","Name mimicking a legitimate service with subtle differences","Auto-start as SYSTEM from a user-writable directory"],"pivots":["service name","image path","account","start type","creating process"],"mits":["M1018","M1024","M1045","M1033","M1047"],"start":{"win":"Start with 7045, filter non-standard ImagePath locations, then correlate to 4688 and 4624.","aws":"Windows-specific; pivot to Lambda or IAM persistence in cloud."},"ref":false},"T1053":{"name":"Scheduled Task / Job","tactic":"Execution","summary":"Task creation by unexpected users, tasks pointing to suspicious binaries or paths, tasks as persistence after initial access.","detect":["Task by a non-admin or process that shouldn't schedule work","Command pointing to temp/appdata, encoded, or random-named binaries","Names mimicking legitimate system tasks with slight variation","Cloud scheduled jobs outside change windows"],"pivots":["task name","task command","creating user","trigger"],"mits":["M1018","M1047","M1028","M1026"],"start":{"win":"Start with 4698, extract <Command> from TaskContent XML, validate 4688 nearby.","aws":"EventBridge rule or Lambda trigger creation by non-standard identities."},"ref":false,"subs":5},"T1547":{"name":"Boot / Logon Autostart","tactic":"Persistence","summary":"Registry run-key modifications, startup folder writes, and service or driver registrations that survive reboots.","detect":["Run/RunOnce key modified with a new executable path","Files dropped into startup folders","Auto-start service or driver outside normal deployment","WMI subscription or task set to fire at startup"],"pivots":["run key path","startup folder","service binary path"],"mits":["M1024","M1022","M1038","M1047"],"start":{"win":"Start with 4657 on Run/RunOnce keys or 7045 for services, then tie to 4688.","aws":"Pivot to cloud persistence mechanisms instead."},"ref":false,"subs":14},"T1546":{"name":"Event Triggered Execution","tactic":"Persistence","summary":"Persistence via system events — WMI subscriptions, IFEO debuggers, screensavers, or accessibility-tool hijacks that run code on a trigger.","detect":["Image File Execution Options 'Debugger' values set on binaries","WMI permanent event subscription creation","Accessibility binaries (sethc, utilman) replaced or debugged"],"pivots":["registry path","WMI namespace","triggered binary"],"mits":["M1024","M1040","M1047","M1038"],"start":{"win":"4657 on Image File Execution Options keys; 4688 for wmic/PowerShell WMI subscription creation.","aws":"Not applicable — see cloud persistence techniques."},"ref":false,"subs":18},"T1562":{"name":"Impair Defenses","tactic":"Stealth","summary":"Disabling or modifying security tools, audit policies, logging, firewalls, or EDR to reduce detection before or during an attack.","detect":["Audit policy disabled — especially process creation, logon, object access","Firewall rules added or disabled via netsh or GPO","Security tool processes terminated or services stopped","ETW AutoLogger keys deleted or modified"],"pivots":["audit category","registry path","service name","log gap"],"mits":["M1018","M1024","M1047","M1040","M1054"],"start":{"win":"Start with 4719 or 4657 on ETW keys, then validate 4688 for the responsible process.","aws":"StopLogging or DeleteTrail, then role assumptions after the gap."},"ref":false},"T1562.002":{"name":"Disable Windows Event Logging","tactic":"Stealth","summary":"Stopping the event log service, clearing logs, or using wevtutil/reg edits to suppress specific audit categories.","detect":["Event Log service stopped or its registry config modified","wevtutil used to clear logs or disable channels","Log files deleted by a non-admin process","Sudden absence of expected events from an active host"],"pivots":["wevtutil cmdline","EventLog registry path","AutoLogger key","log gap"],"mits":["M1018","M1024","M1047","M1029"],"start":{"win":"4688 filtering wevtutil/reg touching EventLog paths, plus 1102 for the log-clear event.","aws":"CloudTrail StopLogging / DeleteTrail as the primary signals."},"ref":false},"T1562.008":{"name":"Disable Cloud Logs","tactic":"Stealth","summary":"Stopping CloudTrail, deleting trails, or narrowing event selectors to suppress audit records before privileged actions.","detect":["StopLogging or DeleteTrail outside approved change windows","PutEventSelectors narrowing trail scope","Create-and-disable pattern — CreateTrail then StopLogging","Delivery failures or S3 gaps after a logging change"],"pivots":["trail name","userIdentity.arn","follow-on API actions"],"mits":["M1018","M1047","M1054"],"start":{"aws":"StopLogging/DeleteTrail, then all API actions by the same identity in the next 30 minutes.","win":"Not applicable — CloudTrail-specific."},"ref":false},"T1070":{"name":"Indicator Removal","tactic":"Stealth","summary":"Clearing event logs, deleting files, wiping command history, or removing artifacts to erase evidence of intrusion.","detect":["Security log cleared (1102) outside maintenance","wevtutil cl / Clear-EventLog execution","History files or artifacts deleted en masse","Cloud trail stopped or deleted"],"pivots":["log clear","deleted path","host","identity"],"mits":["M1029","M1022","M1041","M1047"],"start":{"win":"1102 is the anchor — then rebuild the pre-clear timeline from forwarded logs.","aws":"StopLogging / DeleteTrail, correlate the actor's later activity."},"ref":false,"subs":8},"T1218":{"name":"System Binary Proxy Execution","tactic":"Stealth","summary":"Abuse of signed system binaries (LOLBins) — rundll32, regsvr32, mshta, msiexec — to proxy execution past application control.","detect":["rundll32/regsvr32 with unusual arguments or remote scriptlets","mshta executing remote or inline script","Signed LOLBins spawning interpreters or network connections"],"pivots":["LOLBin name","command line","child process","network dest"],"mits":["M1038","M1042","M1040","M1021"],"start":{"win":"4688 filtering LOLBin names with suspicious arguments, then 5156 for follow-on connections.","aws":"Not applicable."},"ref":false,"subs":14},"T1027":{"name":"Obfuscated / Encoded","tactic":"Stealth","summary":"Encoded, compressed, or obfuscated payloads and command lines used to evade content-based detection.","detect":["-EncodedCommand / base64 blobs in command lines","High-entropy strings or file names","Compressed/encoded payloads decoded at runtime"],"pivots":["command line","entropy","process"],"mits":["M1040","M1049","M1038"],"start":{"win":"4688 with entropy scoring via ut_shannon_lookup (tonumber the shannon field) on process/command fields.","aws":"Not applicable."},"ref":false,"subs":18},"T1036":{"name":"Masquerading","tactic":"Stealth","summary":"Renaming binaries, spoofing system names/paths, or mismatching extensions to appear legitimate.","detect":["System binary names running from non-system paths","Mismatched signer vs file name","Services or tasks mimicking legitimate names"],"pivots":["binary path","expected path","signer","name"],"mits":["M1045","M1038","M1040","M1049"],"start":{"win":"4688 / 7045 comparing binary name to its executing path against a known-good baseline.","aws":"Not applicable."},"ref":false,"subs":12},"T1552":{"name":"Unsecured Credentials","tactic":"Credential Access","summary":"Unusual reads of credential files, registry paths, secrets stores, or key material by users or tools that shouldn't touch them.","detect":["Unexpected access to credential files, history, or private keys","Scripts/backup tools reading secrets outside normal context","API calls retrieving secrets or key material anomalously"],"pivots":["secret path","registry path","secret ID","follow-on logon"],"mits":["M1022","M1027","M1041","M1047"],"start":{"win":"4663 on credential-bearing paths, then validate 4688 and immediate auth activity.","aws":"GetSecretValue, then AssumeRole/ConsoleLogin by the same identity."},"ref":false,"subs":8},"T1003":{"name":"OS Credential Dumping","tactic":"Credential Access","summary":"Extraction of credentials from LSASS, SAM, or NTDS.dit — the classic pivot from single-host to domain compromise.","detect":["LSASS opened by non-system processes (needs Sysmon 10 for full fidelity)","SAM / NTDS.dit / SECURITY hive access or copy","comsvcs.dll MiniDump, procdump against lsass"],"pivots":["target file","accessing process","host","follow-on lateral movement"],"mits":["M1043","M1040","M1026","M1028"],"start":{"win":"4663 on SAM/NTDS.dit/lsass paths; pair with Sysmon EID 10 for LSASS access for best coverage.","aws":"Cloud equivalent is GetSecretValue / credential retrieval."},"note":"Best fidelity needs Sysmon (EID 10 for LSASS access, EID 1 for procdump). Native 4663 covers file-based access to SAM/NTDS.dit only.","ref":false,"subs":8},"T1558":{"name":"Steal / Forge Kerberos Tickets","tactic":"Credential Access","summary":"Kerberoasting, AS-REP roasting, golden/silver tickets — abusing Kerberos to extract or forge credentials.","detect":["Burst of RC4 (0x17) service-ticket requests across many SPNs — kerberoasting","AS-REP requests for accounts without pre-auth","Anomalous TGT lifetimes suggesting forged tickets"],"pivots":["SPN","encryption type","requesting account","source"],"mits":["M1015","M1027","M1026","M1041"],"start":{"win":"4769 filtered to Ticket_Encryption_Type 0x17, grouped by account with a unique-SPN threshold.","aws":"Not applicable."},"ref":false,"subs":5},"T1555":{"name":"Credentials from Password Stores","tactic":"Credential Access","summary":"Harvesting credentials from browsers, keychains, password managers, or cloud secret stores.","detect":["Non-browser process reading browser credential DBs (Login Data)","Access to credential vault files","Bulk secret retrieval from cloud stores"],"pivots":["store path","accessing process","secret ID"],"mits":["M1043","M1022","M1027","M1042"],"start":{"win":"4663 on browser 'Login Data' / vault paths read by unexpected processes.","aws":"GetSecretValue bursts across multiple secrets by one identity."},"ref":false,"subs":6},"T1039":{"name":"Data from Network Share","tactic":"Collection","summary":"Systematic access to shared drives — staging or collection before exfiltration, visible via share enumeration and per-file access.","detect":["Many files accessed across shares in quick succession","Access to shares outside the account's normal scope","Sensitive file types (.kdbx, .pfx, configs) by unexpected users"],"pivots":["share","file path","account","access volume"],"mits":["M1022","M1030","M1057","M1047"],"start":{"win":"5145 per-file volume analysis by account; 5140 for session-level share access.","aws":"S3 access patterns as the cloud equivalent."},"ref":false,"subs":0},"T1071":{"name":"Application Layer Protocol","tactic":"Command and Control","summary":"C2 traffic blended into normal protocols — beaconing patterns, unusual destinations, and processes that shouldn't be talking outbound.","detect":["Regular-interval connections to the same external host — beaconing","Unexpected processes making outbound HTTP/S or DNS","System binaries connecting to non-Microsoft infrastructure"],"pivots":["process","destination","interval pattern","byte counts"],"mits":["M1031","M1037","M1030"],"start":{"win":"5156 outbound, stats by Application_Name and Dest_Address, look for regularity.","aws":"VPC flow logs and unusual egress from workloads."},"ref":false,"subs":5},"T1041":{"name":"Exfiltration Over C2","tactic":"Exfiltration","summary":"Data leaving over the existing command-and-control channel — outbound volume anomalies from compromised hosts.","detect":["Large outbound transfers from hosts with other IOC activity","Sustained connections with high byte counts to external hosts","Outbound byte volume from a host far exceeding its own baseline, on the same channel already used for C2"],"pivots":["byte volume","destination","process","time window"],"mits":["M1031","M1057","M1037"],"start":{"win":"5156 aggregated by volume, correlate with hosts showing other alerts.","aws":"S3 GetObject spikes or unusual data-transfer API patterns."},"ref":false,"subs":0},"T1190":{"name":"Exploit Public-Facing App","tactic":"Initial Access","summary":"Web or application service compromise: shells spawned by server processes, callbacks, and metadata-service access after suspicious requests.","detect":["Web/app service spawning a shell, LOLbin, or downloader","Outbound callback or metadata access right after a request","Service crash/restart near the exploit window"],"pivots":["source IP","user agent","URI","web process parent","new outbound dest"],"mits":["M1050","M1048","M1030","M1051","M1016"],"start":{"win":"4688 for shells parented to web processes (w3wp/httpd/tomcat), then 5156 for callbacks.","aws":"Public-endpoint anomalies, then GetSecretValue or AssumeRole from the same identity."},"ref":false,"subs":0},"T1133":{"name":"External Remote Services","tactic":"Initial Access","summary":"Unusual external access, repeated failures then success, uncommon geo/timing, and the internal activity that follows the remote session.","detect":["RDP/VPN/SSH from a rare source or outside business hours","Repeated failures followed by a successful session","External session followed by shells, transfer, or lateral movement"],"pivots":["gateway IP","external source","auth failures","follow-on activity"],"mits":["M1032","M1035","M1030","M1042"],"start":{"win":"4625 and 4624 around the same gateway/source, then validate follow-on 4688.","aws":"Cloud identity events when remote admin reaches the control plane."},"ref":false,"subs":0},"T1569":{"name":"System Services","tactic":"Execution","summary":"Service control manager abuse, PsExec-style remote execution, and sc.exe used to launch payloads as services.","detect":["sc.exe or PsExec creating and starting a service","Short gap between service install and execution","Service execution from a remote session or lateral chain"],"pivots":["service name","image path","remote IP","logon session"],"mits":["M1040","M1038","M1026","M1035"],"start":{"win":"7045 + 4688, then tie back to the remote session via 4624 logon type 3.","aws":"Not directly applicable — cloud lateral movement uses role assumption."},"ref":false,"subs":3},"T1098":{"name":"Account Manipulation","tactic":"Persistence","summary":"Account attribute changes, role or group modifications, and native tools or APIs used to preserve or elevate access.","detect":["Password, attribute, group, or role changes outside admin workflow","Native account tools followed by login or privilege changes","Cloud identity changes granting admin or bypassing MFA"],"pivots":["target account","changed attribute","group/role","follow-on privileged action"],"mits":["M1032","M1026","M1030","M1018","M1047"],"start":{"win":"4732 group additions and 4720 creation, then test immediate use of the changed account.","aws":"CreateAccessKey, AttachRolePolicy, or CreateUser, then immediate use."},"ref":false,"subs":7},"T1548":{"name":"Abuse Elevation Control","tactic":"Privilege Escalation","summary":"Bypassing elevation controls — UAC bypass, sudo abuse, or cloud policy attachment to gain higher privilege.","detect":["UAC bypass patterns (fodhelper, eventvwr) in process lineage","SeDebug/SeImpersonate assignment to unexpected sessions","Admin policy attached to a role/user in cloud"],"pivots":["process lineage","privilege list","policy ARN"],"mits":["M1026","M1052","M1038","M1047"],"start":{"win":"4672 for privilege assignment, 4688 for known UAC-bypass binaries.","aws":"AttachRolePolicy / AttachUserPolicy granting elevated permissions."},"ref":false,"subs":6},"T1055":{"name":"Process Injection","tactic":"Privilege Escalation","summary":"Injecting code into legitimate processes to hide execution and inherit trust — needs Sysmon for solid coverage.","detect":["CreateRemoteThread into system processes (Sysmon EID 8)","Handle opens to lsass/explorer with suspicious access rights (Sysmon EID 10)","Reflective/module loads from memory"],"pivots":["source process","target process","access rights"],"mits":["M1040","M1026","M1038"],"start":{"win":"Primarily Sysmon EID 8/10; native Security log gives only partial signal via 4688 lineage.","aws":"Not applicable."},"note":"Requires Sysmon (EID 8 CreateRemoteThread, EID 10 ProcessAccess). Native Windows Security auditing does not cover injection well.","ref":false,"subs":12},"T1046":{"name":"Network Service Discovery","tactic":"Discovery","summary":"Port and service scanning to map reachable systems — bursts of connection attempts across hosts and ports.","detect":["One source connecting to many hosts/ports in a short window","Sequential port sweeps in firewall/WFP logs","Scanner user-agents or tooling signatures"],"pivots":["source","dest range","port spread","time window"],"mits":["M1030","M1031","M1037","M1042"],"start":{"win":"5156 aggregated by source with a distinct-destination/port threshold.","aws":"DescribeInstances / DescribeSecurityGroups enumeration in CloudTrail."},"ref":false,"subs":0},"T1005":{"name":"Data from Local System","tactic":"Collection","summary":"Collecting files from the local host — sensitive documents, configs, and credentials staged before exfiltration.","detect":["Bulk file reads of document/config types by unusual processes","Access to sensitive directories outside normal use","Staging into a single archive/folder"],"pivots":["file path","process","volume","archive"],"mits":["M1022","M1057","M1041"],"start":{"win":"4663 on sensitive paths (needs SACLs); pair with 4688 for archiving tools.","aws":"GetObject on sensitive buckets."},"ref":false,"subs":0},"T1530":{"name":"Data from Cloud Storage","tactic":"Collection","summary":"Accessing cloud object storage directly — bulk downloads from S3 or equivalent, often after enumeration.","detect":["High-volume GetObject in a short window","Access to sensitive buckets by unusual identities","Downloads to external IPs"],"pivots":["bucket","identity","object count","source IP"],"mits":["M1022","M1054","M1041","M1057"],"start":{"aws":"GetObject volume thresholds by identity (requires S3 data events).","win":"Local equivalent is T1005 / T1039."},"ref":false,"subs":0},"T1526":{"name":"Cloud Service Discovery","tactic":"Discovery","summary":"Enumerating cloud services, accounts, and resources to orient after gaining access — List/Describe API bursts.","detect":["Many distinct List/Describe calls from one identity quickly","GetCallerIdentity then broad enumeration","Enumeration from a new IP/region for the identity"],"pivots":["identity","API spread","source IP"],"mits":["M1018","M1047","M1054"],"start":{"aws":"ListBuckets/ListUsers/DescribeInstances with a distinct-call threshold per identity.","win":"On-host equivalent is T1087/T1082."},"ref":false,"subs":0},"T1570":{"name":"Lateral Tool Transfer","tactic":"Lateral Movement","summary":"Copying tools or payloads between hosts — often via admin shares — to stage the next hop.","detect":["Executable/archive writes to ADMIN$/C$ from a remote session","File transfer immediately before remote execution","Tools appearing on multiple hosts from one source"],"pivots":["share","file","source host","dest host"],"mits":["M1035","M1030","M1037","M1040"],"start":{"win":"5145 write access to admin shares, then 7045/4688 execution on the destination.","aws":"Not directly applicable."},"ref":false,"subs":0},"T1550":{"name":"Use Alternate Auth Material","tactic":"Lateral Movement","summary":"Pass-the-hash, pass-the-ticket, or stolen session tokens used to authenticate without the plaintext password.","detect":["NTLM logons where Kerberos is expected — possible PtH","Ticket reuse from unexpected hosts","Cloud session token reuse from new IPs"],"pivots":["auth package","logon type","source","account"],"mits":["M1026","M1043","M1015","M1032"],"start":{"win":"4624 filtering Authentication_Package=NTLM for accounts/hosts that should use Kerberos.","aws":"AssumeRole / session token use from anomalous sources."},"ref":false,"subs":4},"T1560":{"name":"Archive Collected Data","tactic":"Collection","summary":"Staging data into archives (zip, rar, 7z) before exfiltration — often the last step before data leaves.","detect":["Archiving tools (rar/7z/zip) spawned near bulk file access","Large archives created in temp/staging directories","Password-protected archives created by unusual users"],"pivots":["process","archive path","source files","volume"],"mits":["M1057","M1022","M1047"],"start":{"win":"4688 for rar/7z/makecab near 5145/4663 bulk file access in the same session.","aws":"Archive-then-upload patterns preceding S3 PutObject/GetObject."},"ref":false,"subs":3},"T1105":{"name":"Ingress Tool Transfer","tactic":"Command and Control","summary":"Downloading tools or payloads into the environment — LOLBin downloaders and second-stage retrieval.","detect":["certutil/bitsadmin/curl/PowerShell downloading files","Binaries written to temp/appdata right after a download","Outbound to file-hosting or low-reputation infrastructure"],"pivots":["process","command line","URL","dropped file"],"mits":["M1031","M1037","M1038","M1021"],"start":{"win":"4688 for certutil/bitsadmin/curl downloaders, then 5156 for the fetch destination.","aws":"Workload egress pulling payloads from external hosts."},"ref":false,"subs":0},"T1572":{"name":"Protocol Tunneling","tactic":"Command and Control","summary":"Tunneling C2 inside another protocol (DNS, HTTP, SSH) to bypass egress controls and blend in.","detect":["High-volume/high-entropy DNS to a single domain — DNS tunneling","SSH or HTTP tunnels to unexpected external hosts","Non-standard use of standard ports"],"pivots":["protocol","destination","query volume","process"],"mits":["M1031","M1037","M1030"],"start":{"win":"5156 by protocol/port anomalies; pair with DNS logs for tunneling patterns.","aws":"VPC flow log egress anomalies to single destinations."},"ref":false,"subs":0},"T1090":{"name":"Proxy","tactic":"Command and Control","summary":"Routing traffic through intermediary proxies or relays to obscure the true C2 destination.","detect":["Connections to known anonymizing proxies or Tor nodes","Internal hosts relaying traffic for others — internal proxy","Multi-hop chains hiding the final destination"],"pivots":["source","proxy host","final destination"],"mits":["M1037","M1031","M1030"],"start":{"win":"5156 outbound to proxy/Tor infrastructure enriched with threat intel.","aws":"Egress to anonymizing infrastructure in flow logs."},"ref":false,"subs":4},"T1595":{"name":"Active Scanning","tactic":"Reconnaissance","summary":"External scanning of your public infrastructure for open ports, services, and vulnerabilities prior to attack.","detect":["Inbound connection sweeps across many ports from one source","Vulnerability-scanner signatures against public assets","Spikes in blocked inbound traffic on the perimeter"],"pivots":["source IP","port spread","target asset"],"mits":["M1056","M1030","M1037"],"start":{"win":"Perimeter/firewall and 5156 inbound on DMZ hosts, aggregated by source.","aws":"VPC flow logs / WAF logs for scanning against public endpoints."},"note":"Largely pre-compromise — best seen at the perimeter (firewall, WAF, IDS) rather than host logs.","ref":false,"subs":3},"T1598":{"name":"Phishing for Information","tactic":"Reconnaissance","summary":"Solicitation of credentials or intel via deceptive messages — a precursor to phishing-based initial access.","detect":["Inbound mail with credential-harvesting links or lookalike domains","Users reporting suspicious information requests","Newly registered lookalike domains contacting staff"],"pivots":["sender","domain","URL","recipient"],"mits":["M1017","M1054","M1021"],"start":{"win":"Primarily email-gateway and proxy telemetry, not host Security logs.","aws":"Not applicable."},"note":"Detected mainly through email security / proxy logs — outside native Windows/CloudTrail scope.","ref":false,"subs":4},"T1589":{"name":"Gather Victim Identity Info","tactic":"Reconnaissance","summary":"Collecting emails, employee names, and credentials from public or breach sources to enable targeting.","detect":["Credential-stuffing using known-breached accounts","OSINT-driven targeting of specific staff","Enumeration of valid usernames via auth responses"],"pivots":["account","source","breach corpus"],"mits":["M1056","M1017"],"start":{"win":"Indirectly — 4625 username-enumeration patterns can hint at prior identity gathering.","aws":"ConsoleLogin failures probing known usernames."},"note":"Mostly external/OSINT activity; limited direct host telemetry.","ref":false,"subs":3},"T1583":{"name":"Acquire Infrastructure","tactic":"Resource Development","summary":"Adversary stand-up of domains, servers, or cloud accounts to host C2 and tooling.","detect":["Connections to newly registered or low-reputation domains","Known adversary infrastructure in threat intel","Fast-flux or disposable hosting patterns"],"pivots":["domain age","ASN","reputation"],"mits":["M1056"],"start":{"win":"5156 outbound enriched with domain-age / reputation intel.","aws":"Egress to newly registered domains from workloads."},"note":"Pre-compromise adversary activity — surfaced via threat-intel enrichment, not direct logs.","ref":false,"subs":8},"T1588":{"name":"Obtain Capabilities","tactic":"Resource Development","summary":"Acquisition of exploits, malware, or code-signing certs to use against targets.","detect":["Known tool/malware hashes appearing in the environment","Use of leaked or fraudulent code-signing certificates","Commodity-tool signatures in execution telemetry"],"pivots":["file hash","signer","tool signature"],"mits":["M1056","M1049"],"start":{"win":"4688 / EDR hash matching against threat intel for known offensive tooling.","aws":"Not directly applicable."},"note":"Detected downstream when the acquired capability is used — pair with threat intel.","ref":false,"subs":7},"T1608":{"name":"Stage Capabilities","tactic":"Resource Development","summary":"Placing payloads on delivery infrastructure — upload sites, compromised hosts, or watering holes.","detect":["Downloads from known staging infrastructure","Payloads pulled from paste/upload sites","Watering-hole redirects to malicious content"],"pivots":["URL","host","payload hash"],"mits":["M1056","M1021"],"start":{"win":"Proxy/5156 egress to staging hosts, then 4688 for the resulting payload execution.","aws":"Not directly applicable."},"note":"Adversary-side staging — mainly visible via proxy/download telemetry.","ref":false,"subs":6},"T1566":{"name":"Phishing","tactic":"Initial Access","summary":"Malicious attachments or links delivering initial access — the most common intrusion entry point.","detect":["Office/PDF spawning script interpreters or LOLBins","Users clicking links to newly registered domains","Attachment execution from mail/temp directories"],"pivots":["parent process","sender","URL","attachment hash"],"mits":["M1017","M1021","M1049","M1031","M1054"],"start":{"win":"4688 for Office→PowerShell/cmd lineage (the on-host tail of the phish).","aws":"Not applicable directly."},"note":"Delivery is seen at the email gateway; the on-host detonation is visible via 4688 process lineage.","ref":false,"subs":4},"T1204":{"name":"User Execution","tactic":"Execution","summary":"A user runs a malicious file or link — the human-triggered step that turns delivery into execution.","detect":["Execution of files from mail/download/temp directories","Double-extension or lure-named files launched","Macro-enabled documents spawning interpreters"],"pivots":["file path","parent process","user"],"mits":["M1017","M1038","M1021","M1049"],"start":{"win":"4688 filtering executions parented to Office/mail/browser from user-writable paths.","aws":"Not applicable."},"ref":false,"subs":5},"T1047":{"name":"Windows Management Instrumentation","tactic":"Execution","summary":"WMI used for execution, reconnaissance, or lateral movement — a favourite living-off-the-land vector.","detect":["wmic process call create for remote/local execution","WmiPrvSE spawning shells or LOLBins","WMI event subscriptions for persistence"],"pivots":["process","command line","target host"],"mits":["M1038","M1040","M1018"],"start":{"win":"4688 for wmic.exe / WmiPrvSE.exe child processes with suspicious arguments.","aws":"Not applicable."},"ref":false,"subs":0},"T1087":{"name":"Account Discovery","tactic":"Discovery","summary":"Enumerating local and domain accounts and groups to plan privilege escalation and lateral movement.","detect":["net user / net group / net localgroup bursts","AD queries enumerating privileged groups","Cloud ListUsers / ListRoles enumeration"],"pivots":["process","command line","query volume"],"mits":["M1028","M1018","M1047"],"start":{"win":"4688 filtering net.exe/dsquery/PowerShell AD enumeration commands.","aws":"ListUsers/ListRoles bursts in CloudTrail (see Cloud enumeration)."},"ref":false,"subs":4},"T1082":{"name":"System Information Discovery","tactic":"Discovery","summary":"Host reconnaissance — OS, hardware, patch level, and configuration used to tailor the next step.","detect":["systeminfo / hostname / wmic bursts after access","Sequences of discovery commands in one session","Cloud DescribeInstances / metadata queries"],"pivots":["process","command sequence","session"],"mits":["M1028","M1047"],"start":{"win":"4688 for systeminfo/whoami/wmic clustered in a single logon session.","aws":"DescribeInstances / metadata-service access."},"ref":false,"subs":0},"T1069":{"name":"Permission Groups Discovery","tactic":"Discovery","summary":"Enumerating security groups to find privileged targets and paths to escalation.","detect":["net group 'Domain Admins' and similar queries","Enumeration of local/remote group membership","Cloud IAM group/role enumeration"],"pivots":["process","group queried","account"],"mits":["M1028","M1018","M1047"],"start":{"win":"4688 filtering net group / net localgroup for privileged groups.","aws":"ListGroups / ListRoles enumeration."},"ref":false,"subs":3},"T1018":{"name":"Remote System Discovery","tactic":"Discovery","summary":"Enumerating other hosts on the network to identify lateral-movement targets.","detect":["net view / nltest / ping sweeps","ARP or DNS enumeration bursts","Cloud DescribeInstances mapping the fleet"],"pivots":["process","dest list","time window"],"mits":["M1030","M1047"],"start":{"win":"4688 for net view/nltest and 5156 sweeps across internal hosts.","aws":"DescribeInstances enumeration."},"ref":false,"subs":0},"T1567":{"name":"Exfiltration Over Web Service","tactic":"Exfiltration","summary":"Data pushed to legitimate web services (cloud storage, paste sites) to blend exfiltration with normal traffic.","detect":["Uploads to file-sharing / paste services from unusual hosts","Large outbound to cloud-storage APIs not normally used","Encoded data in web requests to external services"],"pivots":["destination service","volume","process"],"mits":["M1057","M1037","M1021"],"start":{"win":"5156 outbound to known web-service ranges with volume anomalies.","aws":"Unusual PutObject / external upload patterns."},"ref":false,"subs":4},"T1048":{"name":"Exfiltration Over Alt Protocol","tactic":"Exfiltration","summary":"Using DNS, ICMP, or other non-C2 protocols to smuggle data out of the environment.","detect":["High-volume or high-entropy DNS queries — DNS tunneling","Abnormal ICMP payload volume","Data over non-standard ports"],"pivots":["protocol","query volume","destination"],"mits":["M1031","M1037","M1057"],"start":{"win":"5156 by protocol/port anomalies; pair with DNS logs for tunneling.","aws":"Egress anomalies in VPC flow logs; GetObject to external IPs."},"ref":false,"subs":3},"T1486":{"name":"Data Encrypted for Impact","tactic":"Impact","summary":"High-frequency file modification, ransom-note creation, backup tampering, and storage activity consistent with encryption at scale.","detect":["High-frequency writes/renames with uncommon extensions","Shadow-copy deletion or backup tampering before encryption","Ransom notes across many directories"],"pivots":["file path","process","share/bucket","backup tool","logging state"],"mits":["M1053","M1040","M1030","M1022"],"start":{"win":"4663 + 4688, then test for 7045, 1102, or vssadmin delete in the same window.","aws":"Unusual storage churn, then StopLogging or policy changes around it."},"ref":false,"subs":0},"T1490":{"name":"Inhibit System Recovery","tactic":"Impact","summary":"Deleting shadow copies, backups, and recovery options to prevent restoration — a ransomware precursor.","detect":["vssadmin delete shadows / wbadmin delete catalog","bcdedit disabling recovery","Backup service tampering or deletion"],"pivots":["process","command line","backup target"],"mits":["M1053","M1028","M1018"],"start":{"win":"4688 filtering vssadmin/wbadmin/bcdedit recovery-destruction commands.","aws":"Deletion of snapshots / backup resources in CloudTrail."},"ref":false,"subs":0},"T1489":{"name":"Service Stop","tactic":"Impact","summary":"Stopping security, database, or backup services to maximize impact or disable defenses before encryption.","detect":["net stop / sc stop against AV, EDR, DB, or backup services","Mass service termination in a short window","Security service disabled before other impact"],"pivots":["service","process","host"],"mits":["M1030","M1018","M1022"],"start":{"win":"4688 for net stop/sc stop targeting protected services; 7045/System for state changes.","aws":"Stopping/disabling cloud services via API."},"ref":false,"subs":0},"T1531":{"name":"Account Access Removal","tactic":"Impact","summary":"Deleting or locking accounts, or changing passwords, to deny legitimate users access during an attack.","detect":["Mass password resets or account deletions","Admin locking out other admins","Cloud identity deletion or policy stripping"],"pivots":["account","actor","action"],"mits":["M1032","M1026","M1018"],"start":{"win":"4726 (account deletion) / 4740 lockouts in bulk by one actor.","aws":"DeleteUser / DeleteLoginProfile bursts."},"note":"Native coverage is partial — 4720/4726/4740 give creation/deletion/lockout; pair with IdP logs.","ref":false,"subs":0},"T1592":{"name":"Gather Victim Host Information","tactic":"Reconnaissance","summary":"Host details are collected from public sources and scanning to shape exploit and payload choices before any intrusion.","detect":["Perimeter scanning and banner-grab patterns in edge logs","User-agent anomalies against public-facing assets","External attack-surface tooling identifying your hosts"],"pivots":["SourceIp","DestinationPort","ComputerName"],"mits":["M1056","M1016"],"subs":4,"ref":false,"start":"Only the scanning side is visible — web/WAF and firewall logs. Reduce exposed banner detail rather than trying to alert on collection."},"T1590":{"name":"Gather Victim Network Information","tactic":"Reconnaissance","summary":"Network ranges, DNS, and topology are mapped from public registries and probing to plan the approach.","detect":["DNS zone transfer attempts (AXFR) against your name servers","WHOIS and BGP lookups are invisible; enumeration of your DNS is not","Sequential probing across your public IP ranges"],"pivots":["SourceIp","query","DestinationPort"],"mits":["M1056","M1030"],"subs":6,"ref":false,"start":"Refuse AXFR and alert on attempts. Most of this technique is genuinely unobservable — treat the gap honestly."},"T1591":{"name":"Gather Victim Org Information","tactic":"Reconnaissance","summary":"Org structure, roles, and business relationships are researched to build convincing pretexts for phishing and vishing.","detect":["No direct telemetry — surfaces later as unusually well-targeted phishing","Employee data appearing in external breach or scraping datasets","Pretexts referencing accurate internal detail"],"pivots":["Account_Name","sourceIPAddress"],"mits":["M1056","M1017"],"subs":4,"ref":false,"start":"Not detectable internally. The defensive lever is user training and limiting public org detail."},"T1682":{"name":"Query Public AI Services","tactic":"Reconnaissance","summary":"Public LLMs are used to aggregate and synthesise open-source information about the target, accelerating reconnaissance that once took days into minutes.","detect":["No internal telemetry — the query happens on a third-party service","Effect shows as faster, better-tailored social engineering","Corporate use of AI services may surface in proxy logs, but adversary use will not"],"pivots":["sourceIPAddress","Account_Name"],"mits":["M1056","M1017"],"subs":0,"ref":false,"start":"Externally invisible. Worth staging so your coverage map is honest about it, and worth reflecting in phishing-simulation realism."},"T1597":{"name":"Search Closed Sources","tactic":"Reconnaissance","summary":"Paid intelligence, breach dumps, and criminal marketplaces are mined for credentials and access already available for sale.","detect":["Credential-stuffing success against accounts whose passwords appear in known breaches","Access broker listings referencing your organisation","Authentications with credentials never used internally before"],"pivots":["Account_Name","sourceIPAddress"],"mits":["M1056","M1027","M1032"],"subs":2,"ref":false,"start":"Feed breached-credential intelligence into your identity controls. Detection is downstream — watch for stuffing success on aged credentials."},"T1596":{"name":"Search Open Technical Databases","tactic":"Reconnaissance","summary":"Public technical datasets (certificate transparency, Shodan, DNS records) reveal your exposed infrastructure without touching it.","detect":["Certificate transparency entries revealing internal hostnames","Assets appearing in public scan databases","Newly issued certificates for subdomains you did not expect"],"pivots":["DestinationHostname","SourceIp"],"mits":["M1056","M1016"],"subs":5,"ref":false,"start":"Monitor certificate transparency for your domains — that is the one genuinely actionable feed here."},"T1593":{"name":"Search Open Websites/Domains","tactic":"Reconnaissance","summary":"Public sites, social media, and code repositories are searched for credentials, keys, and technical detail your staff published.","detect":["Secrets discovered in public repositories belonging to your organisation","Employee posts revealing tooling or architecture","Leaked keys later used against your cloud tenant"],"pivots":["Account_Name","userIdentity","sourceIPAddress"],"mits":["M1056","M1017","M1047"],"subs":3,"ref":false,"start":"Run secret scanning against public repos for your org. Leaked-key use is detectable in CloudTrail even though the search is not."},"T1681":{"name":"Search Threat Vendor Data","tactic":"Reconnaissance","summary":"Public threat-intelligence and sandbox reports are mined to learn which of the adversary’s tooling is already burned, and what defenders know about your environment.","detect":["No internal telemetry — the research happens on vendor platforms","Uploaded internal samples may expose your environment publicly","Adversary retooling shortly after a public report"],"pivots":["Hashes","ComputerName"],"mits":["M1056","M1047"],"subs":0,"ref":false,"start":"Not detectable. The practical control is not uploading internal samples to public sandboxes — that is how your environment ends up in this dataset."},"T1594":{"name":"Search Victim-Owned Websites","tactic":"Reconnaissance","summary":"Your own public sites are studied for staff names, technologies, and contact routes to support later social engineering.","detect":["Systematic crawling of your public sites from a single source","Access to staff-directory or careers pages at machine speed","Scraping preceding a phishing campaign"],"pivots":["SourceIp","DestinationHostname"],"mits":["M1056","M1017"],"subs":0,"ref":false,"start":"Web server logs show the crawl. Low value as an alert, but useful context when a phishing wave follows."},"T1650":{"name":"Acquire Access","tactic":"Resource Development","summary":"Access is bought from an initial access broker, so the intrusion begins with working credentials and no exploitation phase at all.","detect":["Successful authentication from a new geography with no preceding failures — bought access looks clean","Valid-account logins with no reconnaissance beforehand","Broker listings referencing your organisation"],"pivots":["Account_Name","sourceIPAddress","Logon_Type","ComputerName"],"mits":["M1032","M1027","M1018","M1056"],"subs":0,"ref":false,"start":{"win":"The tell is the absence of noise — a clean first-time-successful login from a new location. Lean on impossible travel and new-ASN rules rather than failure-based ones."}},"T1586":{"name":"Compromise Accounts","tactic":"Resource Development","summary":"Existing third-party accounts are taken over to lend credibility to later phishing and infrastructure registration.","detect":["Mail from known partner addresses with anomalous headers or sending infrastructure","Partner accounts messaging your staff outside established patterns","SPF/DKIM passing but sending IP unusual for that domain"],"pivots":["sourceIPAddress","Account_Name"],"mits":["M1056","M1017","M1032"],"subs":3,"ref":false,"start":"Mail gateway telemetry. Trusted-partner compromise defeats reputation controls — header and sending-IP anomalies are the remaining signal."},"T1584":{"name":"Compromise Infrastructure","tactic":"Resource Development","summary":"Third-party servers and domains are compromised and used to host the operation, so traffic goes to reputable, aged infrastructure.","detect":["Connections to legitimate domains serving unexpected content","Aged domains suddenly hosting payload paths","Reputation feeds flagging previously clean infrastructure"],"pivots":["DestinationHostname","DestinationIp","Image"],"mits":["M1056","M1031","M1037"],"subs":8,"ref":false,"start":"Domain age and reputation heuristics fail here by design. Behavioural rules on the host side are the reliable fallback."},"T1587":{"name":"Develop Capabilities","tactic":"Resource Development","summary":"Custom malware, certificates, and exploits are built in-house, so hash and signature-based detection has nothing to match.","detect":["Novel binaries with no prevalence anywhere in your estate — dc(ComputerName)=1 and unknown hash","Self-signed or newly issued code-signing certificates","Behaviour-based detections firing where signature-based ones do not"],"pivots":["Hashes","Signed","Signature","Image","ComputerName"],"mits":["M1056","M1040","M1049"],"subs":4,"ref":false,"start":{"win":"Prevalence scoring is the answer: a binary seen on exactly one host, unsigned, running from a user path is worth investigating regardless of hash reputation."}},"T1585":{"name":"Establish Accounts","tactic":"Resource Development","summary":"Personas and accounts are created ahead of time to age infrastructure and build credibility before contact.","detect":["Inbound contact from recently created social or email accounts","Newly registered domains with plausible lookalike names","First-contact messages from addresses with no history"],"pivots":["sourceIPAddress","Account_Name"],"mits":["M1056","M1017"],"subs":3,"ref":false,"start":"Domain-age and first-time-sender rules at the mail gateway are the practical control."},"T1genc":{"name":"Generate Content","tactic":"Resource Development","summary":"Generative tooling produces convincing phishing text, voice, or video, removing the language and quality errors defenders historically relied on as tells.","detect":["Phishing with no linguistic errors and accurate internal context","Voice or video pretexts in payment-approval workflows","Campaigns with high message variation and no reused text"],"pivots":["Account_Name","sourceIPAddress"],"mits":["M1056","M1017","M1032"],"subs":2,"ref":false,"start":"Not detectable internally, and it removes a signal you used to have. Compensate with out-of-band verification for payment and access changes rather than teaching staff to spot bad grammar."},"T1659":{"name":"Content Injection","tactic":"Initial Access","summary":"Traffic is modified in transit from a compromised network position, delivering payloads inside otherwise legitimate downloads.","detect":["Downloads whose hash differs from the vendor-published hash","Update traffic served over plain HTTP returning unexpected content","Unexplained redirects in proxy logs before a payload download"],"pivots":["DestinationIp","DestinationHostname","DestinationPort","Image","ComputerName"],"mits":["M1031","M1037","M1045"],"subs":0,"ref":false,"start":{"win":"Proxy logs plus hash verification of downloaded binaries. Mostly a network-position problem — enforce HTTPS and signature checks."}},"T1189":{"name":"Drive-by Compromise","tactic":"Initial Access","summary":"A user visits a compromised or malicious site and code executes through the browser with no interaction beyond browsing.","detect":["Browser processes spawning shells or writing executables (Sysmon EID 1/11)","Browser child processes running from Temp or Downloads","Proxy logs showing redirect chains ending at newly registered domains"],"pivots":["ParentImage","Image","TargetFilename","DestinationHostname"],"mits":["M1021","M1048","M1051","M1050"],"subs":0,"ref":false,"start":{"win":"The browser-spawns-shell rule (4688/Sysmon EID 1 with browser ParentImage) is high fidelity — build it once and it covers many delivery paths."}},"T1200":{"name":"Hardware Additions","tactic":"Initial Access","summary":"Physical devices are added to the network or a host — rogue APs, implants, or malicious HID devices that type on the user’s behalf.","detect":["New device enumeration on managed endpoints (HID devices appearing unexpectedly)","Unknown MAC addresses on switch ports","Keystroke injection patterns — impossibly fast input followed by execution"],"pivots":["Image","CommandLine","ComputerName"],"mits":["M1042","M1030","M1035"],"subs":0,"ref":false,"start":{"win":"Device installation events plus NAC/switch port data. Correlate with T1674 Input Injection for the HID attack path."}},"T1091":{"name":"Replication Through Removable Media","tactic":"Initial Access","summary":"Malware spreads via USB, crossing air gaps and network segmentation that other controls rely on.","detect":["Executables or LNK files written to removable drives","Autorun-style files appearing on media","Same binary hash appearing across hosts with no network path between them"],"pivots":["TargetFilename","Image","Hashes","ComputerName"],"mits":["M1042","M1049","M1038"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 11 on removable paths plus EID 1 hash correlation across hosts. Disable autorun by policy."}},"T1195":{"name":"Supply Chain Compromise","tactic":"Initial Access","summary":"Trusted software or a dependency is backdoored upstream, so the malicious code arrives through your own patching process with valid signatures.","detect":["Update processes writing unexpected binaries or spawning shells","New outbound destinations appearing immediately after a software update","Hash mismatches against vendor-published values"],"pivots":["ParentImage","Image","Hashes","DestinationHostname","ComputerName"],"mits":["M1051","M1045","M1016","M1047"],"subs":3,"ref":false,"start":{"win":"Sysmon EID 1 hash logging plus EID 3. Watch for updater processes doing anything other than updating — that is the detectable moment."}},"T1199":{"name":"Trusted Relationship","tactic":"Initial Access","summary":"A supplier, MSP, or partner with legitimate access is compromised and used as the entry path, arriving through channels you deliberately allow.","detect":["Third-party accounts authenticating outside contracted hours or from new geographies","Partner accounts accessing systems beyond their normal scope","Vendor remote-access tooling running on unexpected hosts"],"pivots":["Account_Name","sourceIPAddress","Logon_Type","ComputerName"],"mits":["M1018","M1026","M1030","M1032"],"subs":0,"ref":false,"start":{"win":"Tag third-party accounts explicitly in a lookup, then baseline their normal hosts and hours. Deviation is the detection."}},"T1669":{"name":"Wi-Fi Networks","tactic":"Initial Access","summary":"Access is gained over wireless — an open network, stolen credentials, or a compromised dual-homed neighbour bridging into the target.","detect":["Authentications from wireless segments by accounts that normally connect wired","Dual-homed hosts bridging wireless and wired networks","New devices associating with corporate SSIDs outside onboarding"],"pivots":["SourceIp","Account_Name","ComputerName","Logon_Type"],"mits":["M1032","M1030","M1027","M1035"],"subs":0,"ref":false,"start":{"win":"Wireless controller logs correlated with 4624 source addresses. Dual-homed hosts deserve their own inventory rule."}},"T1197":{"name":"BITS Jobs","tactic":"Execution","summary":"BITS transfers and executes in the background under svchost, surviving reboots and blending into normal update traffic. It is both a download channel and a persistence mechanism.","detect":["bitsadmin.exe or PowerShell Start-BitsTransfer execution, especially with /SetNotifyCmdLine","BITS-Client operational log (EID 3/59/60) showing jobs with external or unusual URLs","svchost.exe making outbound connections to newly seen domains (Sysmon EID 3)"],"pivots":["CommandLine","Image","DestinationHostname","Account_Name"],"mits":["M1037","M1042","M1040"],"subs":0,"ref":false,"start":{"win":"Enable the Microsoft-Windows-Bits-Client/Operational channel — it is off by default and is where the job detail lives. 4688 catches bitsadmin.exe usage."}},"T1651":{"name":"Cloud Administration Command","tactic":"Execution","summary":"Cloud management agents (SSM, RunCommand) execute commands inside VMs, giving an adversary with cloud credentials direct host execution without touching the network.","detect":["SendCommand / RunCommand API calls by principals that do not normally use them","Commands executed against many instances at once","Agent-spawned processes on hosts with no corresponding change ticket"],"pivots":["eventName","userIdentity","ParentImage","ComputerName"],"mits":["M1026","M1018","M1047"],"subs":0,"ref":false,"start":{"aws":"CloudTrail ssm:SendCommand — alert on non-automation principals.","win":"4688 with ParentImage of the SSM/Azure agent reveals the host-side result."}},"T1609":{"name":"Container Administration Command","tactic":"Execution","summary":"The container runtime API is used to execute inside containers, bypassing host-level controls and often without authentication.","detect":["kubectl exec or docker exec activity from unexpected identities","Container runtime API access from outside the control plane","Shells spawned inside containers that should be immutable"],"pivots":["Account_Name","eventName","Image","ComputerName"],"mits":["M1026","M1030","M1035","M1047"],"subs":0,"ref":false,"start":"Kubernetes and container runtime audit logs. Exec into a production container should be rare and alertable."},"T1610":{"name":"Deploy Container","tactic":"Execution","summary":"A malicious container is deployed to run payloads with the cluster’s trust and network reach.","detect":["Pod or container creation from unexpected images or registries","Containers deployed with privileged flags or host mounts","Deployments outside CI pipelines"],"pivots":["Account_Name","eventName","Image"],"mits":["M1026","M1045","M1047","M1030"],"subs":0,"ref":false,"start":"Orchestrator audit logs plus admission control. Enforce image provenance at admission rather than detecting after."},"T1675":{"name":"ESXi Administration Command","tactic":"Execution","summary":"Commands are executed on guest VMs through the hypervisor’s tooling, bypassing guest network controls and often guest logging.","detect":["vmtoolsd spawning shells or unexpected processes inside guests","vSphere guest operations API usage outside automation","Hypervisor-originated execution across many VMs at once"],"pivots":["ParentImage","Image","Account_Name","ComputerName"],"mits":["M1026","M1030","M1047","M1032"],"subs":0,"ref":false,"start":{"win":"4688 with ParentImage=vmtoolsd.exe inside guests is the host-side tell; pair with vCenter audit logs for the initiating account."}},"T1203":{"name":"Exploitation for Client Execution","tactic":"Execution","summary":"A document, browser, or plugin vulnerability executes attacker code with no user-visible launch. The reliable signal is the parent-child relationship: an office or browser process spawning a shell or dropping executables.","detect":["4688/Sysmon EID 1 where ParentImage is winword.exe, excel.exe, outlook.exe, acrord32.exe, or a browser and the child is cmd/powershell/wscript/mshta/rundll32","Browser or Office process writing an executable or script to disk (Sysmon EID 11) then that file executing within minutes","Crashes of client applications (WER / Application log 1000) immediately followed by anomalous child processes"],"pivots":["ParentImage","Image","CommandLine","TargetFilename","ProcessGuid"],"mits":["M1048","M1050","M1051"],"subs":0,"ref":false,"start":{"win":"4688 with command line auditing plus Sysmon EID 1 and 11. The office-spawns-shell pattern is one of the highest-fidelity detections available — build it first."}},"T1574":{"name":"Hijack Execution Flow","tactic":"Execution","summary":"A legitimate signed program is made to load an attacker DLL — sideloading, search-order hijack, or a patched path. The running process name and signature both look clean.","detect":["Sysmon EID 7 signed binaries loading unsigned DLLs from their own working directory","Common sideload targets (rundll32, msiexec, OneDrive updaters) running from non-standard paths","Sysmon EID 11 DLLs written next to a legitimate executable in a user-writable directory"],"pivots":["Image","ImageLoaded","Signed","TargetFilename","ComputerName"],"mits":["M1038","M1040","M1022","M1045"],"subs":12,"ref":false,"start":{"win":"Sysmon EID 7 is mandatory here. Rule: ImageLoaded is unsigned AND its directory equals the Image directory AND that directory is user-writable."}},"T1674":{"name":"Input Injection","tactic":"Execution","summary":"Keystrokes are simulated to drive the UI on the user’s behalf — via malicious HID hardware or software automation — so actions appear user-initiated.","detect":["New HID devices enumerating immediately before shell execution","PowerShell or cmd launched via Run dialog patterns with no user present","SendKeys or automation API usage in script block logs"],"pivots":["CommandLine","ScriptBlockText","ParentImage","ComputerName"],"mits":["M1042","M1040","M1017"],"subs":0,"ref":false,"start":{"win":"Correlate device installation events with 4688 within a short window. Explorer spawning a shell moments after a HID appears is the signature."}},"T1559":{"name":"Inter-Process Communication","tactic":"Execution","summary":"Execution is brokered through COM or named pipes so the malicious action appears to come from a trusted broker process such as explorer.exe or a DCOM server, breaking naive parent-child logic.","detect":["Sysmon EID 17/18 named pipe creation and connection with unusual pipe names (random, or mimicking known C2 frameworks)","DCOM lateral execution: mmc.exe, excel.exe, or dllhost.exe spawning shells, especially with a network logon (4624 type 3) just before","Unexpected processes registering COM servers under HKCU\\Software\\Classes\\CLSID"],"pivots":["PipeName","Image","ParentImage","Target_Logon_ID","ComputerName"],"mits":["M1040","M1026"],"subs":3,"ref":false,"start":{"win":"Sysmon EID 17/18 for pipes (noisy — baseline aggressively with outputlookup). Correlate DCOM execution with 4624 type 3 from the same source."}},"T1106":{"name":"Native API","tactic":"Execution","summary":"Malware calls Windows API functions directly instead of spawning a command interpreter, so there is no cmd.exe or powershell.exe child process to catch. Detection shifts from process lineage to image loads and unusual API-heavy behaviour.","detect":["Sysmon EID 7 image loads of ntdll.dll / kernelbase.dll by unsigned or unusual binaries running from user-writable paths","Processes with no command-line arguments but heavy network or file activity — a classic sign of API-driven implants","Office applications loading scripting or networking DLLs (vbe7.dll, wininet.dll) without a corresponding child process"],"pivots":["Image","ImageLoaded","Signed","ParentImage","ProcessGuid"],"mits":["M1040","M1038"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 7 (ImageLoad) is essential — Security 4688 alone will not see this. Baseline signed-binary image loads first, then alert on unsigned loads from AppData/Temp/ProgramData."}},"T1677":{"name":"Poisoned Pipeline Execution","tactic":"Execution","summary":"CI/CD configuration or referenced build files are modified so the pipeline itself executes attacker code with build-system credentials.","detect":["Changes to CI config files (.gitlab-ci.yml, workflow YAML) by unexpected committers","Build jobs making outbound connections to new destinations","Pipeline runs triggered from forked pull requests touching build config"],"pivots":["Account_Name","eventName","DestinationHostname"],"mits":["M1026","M1045","M1047","M1018"],"subs":0,"ref":false,"start":"Source control and CI audit logs. Require review for build-config changes and restrict fork-triggered pipelines."},"T1648":{"name":"Serverless Execution","tactic":"Execution","summary":"Serverless functions or automation rules run attacker code with a service identity, persisting outside any host you monitor.","detect":["Function creation or modification by unexpected principals","Functions with broad IAM roles created outside pipelines","Event-source mappings added to trigger on unusual events"],"pivots":["eventName","userIdentity","requestParameters"],"mits":["M1026","M1018","M1047"],"subs":0,"ref":false,"start":{"aws":"CloudTrail lambda:CreateFunction / UpdateFunctionCode / CreateEventSourceMapping by non-pipeline principals."}},"T1129":{"name":"Shared Modules","tactic":"Execution","summary":"Adversaries load malicious DLLs via legitimate loader mechanisms. The payload runs inside a trusted process, so process-name-based detection fails and you must watch what gets loaded rather than what gets launched.","detect":["Sysmon EID 7 image loads from user-writable directories (AppData, Temp, ProgramData, Public)","DLLs loaded by name from a working directory rather than System32 — sideloading candidates","rundll32.exe / regsvr32.exe loading DLLs with unusual export names or from network paths"],"pivots":["ImageLoaded","Image","Signed","SignatureStatus","CommandLine"],"mits":["M1038","M1040"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 7 with a tuned include-list. Consider AppLocker/WDAC in audit mode (EID 8003/8004) to surface non-approved DLL loads cheaply."}},"T1072":{"name":"Software Deployment Tools","tactic":"Execution","summary":"Adversaries abuse SCCM, Intune, or similar deployment platforms to push payloads fleet-wide from a trusted source. Because the tooling is legitimate and privileged, one compromised console equals mass execution.","detect":["Deployment agent processes (ccmexec.exe, ntrmgr.exe) spawning unexpected children on many hosts in a short window","dc(ComputerName) spike — the same new binary executing across dozens of hosts simultaneously is deployment-tool behaviour","Package or application creation events in the deployment platform outside change windows or by unexpected operators"],"pivots":["ParentImage","Image","ComputerName","Account_Name","CommandLine"],"mits":["M1026","M1018","M1030"],"subs":0,"ref":false,"start":{"win":"4688 with ParentImage of your deployment agent, scored by dc(ComputerName). Ingest the SCCM/Intune audit logs — the console-side action is the earlier and cleaner signal."}},"T1127":{"name":"Trusted Developer Utilities Proxy Execution","tactic":"Execution","summary":"Signed Microsoft developer tools (msbuild, dnx, msxsl) compile and run attacker code, so execution is performed by a trusted, allow-listed binary.","detect":["msbuild.exe executing with an inline-task project file, especially from Temp or AppData","Developer utilities running on hosts with no development role","These binaries spawning network connections or child shells (Sysmon EID 1 / 3)"],"pivots":["Image","CommandLine","ParentImage","DestinationIp","ComputerName"],"mits":["M1038","M1042","M1040"],"subs":3,"ref":false,"start":{"win":"4688 with command-line auditing; msbuild.exe on a non-developer workstation is close to zero-false-positive. Use dc(ComputerName) to spot fleet-wide use."}},"T1037":{"name":"Boot or Logon Initialization Scripts","tactic":"Persistence","summary":"Logon scripts execute automatically for a user or, via GPO, for everyone in scope. Domain-level logon scripts give an adversary fleet-wide execution from a single SYSVOL write.","detect":["4657 writes to HKCU\\Environment\\UserInitMprLogonScript — the classic per-user logon-script key","Sysmon EID 11 writes to SYSVOL scripts directories, especially by non-admin accounts","userinit.exe or explorer.exe spawning script interpreters at logon time"],"pivots":["Object_Name","New_Value","TargetFilename","ParentImage","Account_Name"],"mits":["M1024","M1022","M1026"],"subs":5,"ref":false,"start":{"win":"4657 needs a SACL on the Environment key. SYSVOL writes are the higher-impact signal — audit that share explicitly."}},"T1671":{"name":"Cloud Application Integration","tactic":"Persistence","summary":"A malicious OAuth application is added to the tenant, granting persistent API access to mail and files that survives password resets and MFA.","detect":["New application registrations or service principals with broad delegated permissions","Admin consent granted outside change windows","Applications accessing mail or files immediately after consent"],"pivots":["eventName","userIdentity","Account_Name","sourceIPAddress"],"mits":["M1018","M1026","M1047","M1032"],"subs":0,"ref":false,"start":"Identity-provider audit logs for consent and service principal creation. Restrict user consent so admin approval is required."},"T1554":{"name":"Compromise Host Software Binary","tactic":"Persistence","summary":"A legitimate binary users already trust is replaced or patched, so execution looks entirely normal and survives until the file is compared against a known-good hash.","detect":["Sysmon EID 11 modification of executables in Program Files or System32 outside patching windows","Signature status changing from valid to invalid/unsigned for a previously signed binary (Sysmon EID 1 Signed field)","Hash of a common binary differing across your fleet — compare by dc(ComputerName)"],"pivots":["TargetFilename","Hashes","Signed","SignatureStatus","Image"],"mits":["M1045","M1022","M1049"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 1 hash logging plus EID 11. Fleet-wide hash comparison for a given Image name is the strongest available check."}},"T1543":{"name":"Create or Modify System Process","tactic":"Persistence","summary":"Services run as SYSTEM at boot, making them the most valuable persistence primitive on Windows. Creation is loud if you are watching 7045 — most environments create very few new services legitimately.","detect":["7045 service installed with an ImagePath in a user-writable path, or containing powershell/cmd/rundll32","4697 service installed (Security log) correlated with the installing account","sc.exe / New-Service execution followed within seconds by a service start (7036)"],"pivots":["Service_File_Name","Service_Name","Account_Name","ComputerName","CommandLine"],"mits":["M1040","M1026","M1024","M1045"],"subs":5,"ref":false,"start":{"win":"7045 (System log) is the workhorse. Suppress your known-good ImagePath set via outputlookup, then score the remainder by dc(ComputerName)."}},"T1668":{"name":"Exclusive Control","tactic":"Persistence","summary":"The adversary locks out competitors or defenders by taking exclusive hold of a resource — patching the entry vulnerability behind them or killing rival implants.","detect":["A vulnerability being patched with no corresponding change ticket","Processes terminating other suspicious processes","Firewall rules blocking access to a service the adversary just used"],"pivots":["Image","CommandLine","Rule_Name","ComputerName"],"mits":["M1047","M1040","M1026"],"subs":0,"ref":false,"start":{"win":"Unexplained remediation is the paradoxical signal — an unplanned patch or a suddenly closed port can mean someone else closed the door behind themselves."}},"T1525":{"name":"Implant Internal Image","tactic":"Persistence","summary":"A backdoored container or VM image is planted in an internal registry, so every future deployment from that image is compromised. It is persistence at the supply level rather than the host level.","detect":["Image push events to internal registries by unexpected identities or outside CI pipelines","Images whose layers differ from the CI-produced digest for the same tag","Containers running with unexpected entrypoints or launching shells at start"],"pivots":["Account_Name","eventName","userIdentity","ComputerName"],"mits":["M1045","M1026","M1047"],"subs":0,"ref":false,"start":{"win":"Ingest registry audit logs; on Windows hosts watch for docker/containerd activity via 4688.","aws":"CloudTrail ecr:PutImage and ecr:BatchDeleteImage by non-pipeline principals."}},"T1556":{"name":"Modify Authentication Process","tactic":"Persistence","summary":"The authentication stack itself is subverted — a malicious SSP, a patched LSASS, or a registered auth provider — so the adversary can log in as anyone and legitimate credentials keep working.","detect":["4657 writes to LSA Security Packages / Authentication Packages registry values","Sysmon EID 7 unsigned DLLs loading into lsass.exe","New credential providers registered under HKLM\\...\\Authentication\\Credential Providers"],"pivots":["Object_Name","New_Value","ImageLoaded","Image","ComputerName"],"mits":["M1043","M1024","M1026","M1032"],"subs":9,"ref":false,"start":{"win":"SACL the LSA registry keys for 4657, and watch Sysmon EID 7 loads into lsass.exe. Enable LSA protection (RunAsPPL) to reduce the attack surface."}},"T1112":{"name":"Modify Registry","tactic":"Persistence","summary":"The registry is where most Windows persistence and defence-weakening lands. The technique is broad, so value comes from watching a curated set of security-relevant keys rather than everything.","detect":["4657 registry value writes to Run keys, service ImagePath, Winlogon Shell/Userinit, and Image File Execution Options","Sysmon EID 13 value sets by processes running from user-writable paths","reg.exe or powershell writing to HKLM keys from a non-admin workflow"],"pivots":["Object_Name","New_Value","Image","Account_Name","ComputerName"],"mits":["M1024","M1040","M1026"],"subs":0,"ref":false,"start":{"win":"4657 needs a SACL on the specific keys plus Audit Registry enabled — it will not fire otherwise. Object_Name is the key path and New_Value is the written data."}},"T1137":{"name":"Office Application Startup","tactic":"Persistence","summary":"Persistence hides in Office itself — templates, add-ins, or macros that reload every time the user opens Word or Outlook. It survives reimaging of the payload and is rarely inspected.","detect":["Sysmon EID 11 writes to Startup, XLSTART, or Word STARTUP template folders, or to %APPDATA%\\Microsoft\\Templates","Registry writes (4657 / Sysmon EID 13) under Software\\Microsoft\\Office\\*\\Addins","Outlook rules or home-page changes made programmatically rather than through the UI"],"pivots":["TargetFilename","Object_Name","New_Value","Image","Account_Name"],"mits":["M1040","M1042","M1051"],"subs":6,"ref":false,"start":{"win":"Sysmon EID 11 with a path include-list for Office template/add-in directories, plus a SACL and 4657 on the Addins registry keys."}},"T1653":{"name":"Power Settings","tactic":"Persistence","summary":"Sleep and hibernation are disabled so the host stays reachable for C2 and lateral movement rather than dropping off the network overnight.","detect":["powercfg execution disabling standby, hibernate, or monitor timeout","Registry writes to power scheme settings on workstations","Hosts that stop sleeping outside policy — sustained overnight availability"],"pivots":["CommandLine","Object_Name","New_Value","ComputerName"],"mits":["M1024","M1028","M1026"],"subs":0,"ref":false,"start":{"win":"4688 for powercfg with /change or /x arguments. Low volume on workstations and a useful corroborating signal alongside persistence findings."}},"T1542":{"name":"Pre-OS Boot","tactic":"Persistence","summary":"Code is planted in the bootloader or firmware so it runs before Windows and before any security product loads. Detection from inside the OS is limited — prevention and integrity attestation matter more.","detect":["Raw disk writes to boot sectors (Sysmon EID 9 RawAccessRead / write to \\\\.\\PhysicalDrive)","bcdedit.exe modifications disabling integrity checks or recovery","Secure Boot / measured boot attestation failures at startup"],"pivots":["Image","CommandLine","Device","ComputerName"],"mits":["M1046","M1051","M1026"],"subs":5,"ref":false,"start":{"win":"Sysmon EID 9 plus 4688 for bcdedit. Accept that in-OS visibility is partial — pair with TPM attestation where you have it."}},"T1505":{"name":"Server Software Component","tactic":"Persistence","summary":"A web shell or malicious module is planted inside a legitimate server (IIS, Exchange, SQL). It inherits the service account and survives reboots, and because traffic arrives over normal HTTPS it is invisible to network controls.","detect":["w3wp.exe / httpd spawning cmd.exe, powershell.exe, or net.exe — a web server should almost never spawn a shell","Sysmon EID 11 file writes of .aspx/.asmx/.php into web root directories by the web service account","IIS module or Exchange transport agent registration outside patch windows (7045 or application-specific logs)"],"pivots":["ParentImage","Image","TargetFilename","CommandLine","ComputerName"],"mits":["M1042","M1045","M1026"],"subs":6,"ref":false,"start":{"win":"4688/Sysmon EID 1 filtered to ParentImage=w3wp.exe plus Sysmon EID 11 scoped to web root paths. Both are low-volume and high-fidelity."}},"T1176":{"name":"Software Extensions","tactic":"Persistence","summary":"A browser or IDE extension provides persistence and data access with no binary on disk to detect. It runs whenever the user opens the browser and can read every session the user has.","detect":["Sysmon EID 11 writes into browser Extensions directories outside of an update process","Registry writes to ExtensionInstallForcelist — attacker-forced extension deployment via policy","Browser processes making outbound connections to newly seen domains shortly after an extension appears"],"pivots":["TargetFilename","Object_Name","New_Value","Image"],"mits":["M1040","M1042","M1051"],"subs":2,"ref":false,"start":{"win":"Sysmon EID 11 scoped to browser profile paths, plus 4657 on the ExtensionInstallForcelist keys."}},"T1205":{"name":"Traffic Signaling","tactic":"Persistence","summary":"A dormant implant wakes only on a specific packet or port-knock sequence, so there is no persistent beacon to find. Traffic looks like noise until you correlate the trigger with subsequent activity.","detect":["Sysmon EID 3 short-lived inbound connections to unusual ports followed by outbound C2 from the same host","Processes binding raw sockets or listening on high ports without a business reason","Firewall accepts on non-standard ports preceding a spike in outbound traffic"],"pivots":["SourceIp","DestinationPort","Image","ComputerName"],"mits":["M1037","M1030","M1031"],"subs":2,"ref":false,"start":{"win":"Sysmon EID 3 plus perimeter flow logs. The tell is sequence: inbound trigger, then outbound beacon within a short window."}},"T1134":{"name":"Access Token Manipulation","tactic":"Privilege Escalation","summary":"Tokens are stolen or forged so actions run under another identity. The account in the event log is not the account that initiated the action, which quietly breaks attribution.","detect":["4624 logon type 9 (NewCredentials) — runas /netonly behaviour, uncommon outside admin tooling","4672 special privileges assigned to accounts that should not hold SeDebugPrivilege or SeImpersonatePrivilege","Processes opening handles to lsass or other users’ processes (Sysmon EID 10)"],"pivots":["Logon_Type","Privilege_List","SourceImage","TargetImage","Account_Name"],"mits":["M1026","M1018","M1040"],"subs":5,"ref":false,"start":{"win":"4624 type 9 and 4672 privilege assignment. Sysmon EID 10 (ProcessAccess) is high-volume — scope it to lsass and known-sensitive targets."}},"T1484":{"name":"Domain or Tenant Policy Modification","tactic":"Privilege Escalation","summary":"GPO or tenant policy is edited to push execution or weaken controls domain-wide. One write to a linked GPO can own every machine in scope, which makes this among the highest-impact AD techniques.","detect":["5136 directory service object modification on groupPolicyContainer objects","Sysmon EID 11 writes into SYSVOL Policies folders, particularly scripts or scheduled task XML","GPO edits by accounts outside your delegated GPO-admin group, or outside change windows"],"pivots":["Object_Name","Account_Name","Attribute_LDAP_Display_Name","ComputerName"],"mits":["M1015","M1026","M1018","M1047"],"subs":2,"ref":false,"start":{"win":"Enable Directory Service Changes auditing for 5136 and forward DC logs. Pair with SYSVOL file-write monitoring — the two together are conclusive."}},"T1611":{"name":"Escape to Host","tactic":"Privilege Escalation","summary":"A container breakout puts the adversary on the underlying node, converting a contained workload compromise into full host access.","detect":["Containers launched privileged, with hostPID/hostNetwork, or mounting the host filesystem or docker socket","Processes inside containers accessing /proc/self or host mount paths","Node-level shells originating from container runtime processes"],"pivots":["Image","CommandLine","ParentImage","ComputerName"],"mits":["M1048","M1038","M1026","M1047"],"subs":0,"ref":false,"start":{"win":"Container runtime and orchestrator audit logs; Windows Security logs will not cover this. Alert on privileged/hostPath pod specs at admission."}},"T1068":{"name":"Exploitation for Privilege Escalation","tactic":"Privilege Escalation","summary":"A kernel or service vulnerability lifts the adversary to SYSTEM without credentials. There is no logon event, so process lineage and crash artefacts are the detection surface.","detect":["A medium-integrity process spawning a SYSTEM-integrity child (Sysmon EID 1 IntegrityLevel transition)","Service or driver crashes (System 7031, Application 1000) followed by privileged process creation","Vulnerable-driver loads — Sysmon EID 6 for known BYOVD driver hashes"],"pivots":["IntegrityLevel","ParentImage","Image","ImageLoaded","ComputerName"],"mits":["M1051","M1050","M1038","M1040"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 1 IntegrityLevel and EID 6 driver loads. Maintain a blocklist of known vulnerable drivers — BYOVD is the dominant path."}},"T1612":{"name":"Build Image on Host","tactic":"Stealth","summary":"A container image is built locally to avoid pulling a flagged image from a registry, sidestepping registry-based scanning entirely.","detect":["Docker build activity on hosts that are not build servers","Image builds referencing external base images outside CI","Containers running from images with no registry provenance"],"pivots":["Image","CommandLine","ComputerName"],"mits":["M1038","M1045","M1047","M1030"],"subs":0,"ref":false,"start":"Container runtime logs. Restrict the build API to CI hosts and require registry provenance at admission."},"T1622":{"name":"Debugger Evasion","tactic":"Stealth","summary":"Malware detects analysis tooling and alters behaviour. Like sandbox evasion, its practical SOC value is as a corroborating artefact rather than a primary alert.","detect":["IsDebuggerPresent / CheckRemoteDebuggerPresent patterns in script block or EDR API telemetry","Processes terminating immediately when analysis tools are running","Queries enumerating running processes for debugger names (correlate with T1057)"],"pivots":["ScriptBlockText","CommandLine","Image"],"mits":["M1040"],"subs":0,"ref":false,"start":{"win":"Mostly EDR-sourced. Treat as an enrichment signal on an existing detection rather than a standalone rule."}},"T1678":{"name":"Delay Execution","tactic":"Stealth","summary":"The payload sleeps or schedules itself to run later, decoupling the malicious action from the initial intrusion and defeating short analysis windows.","detect":["Long sleep/timeout commands preceding execution (timeout.exe, Start-Sleep with large values)","Scheduled tasks created with a distant or randomised start time","Processes spawning hours after their parent installed them — correlate by ProcessGuid"],"pivots":["CommandLine","Image","ProcessGuid","ComputerName"],"mits":["M1040","M1047"],"subs":0,"ref":false,"start":{"win":"4688 and 4698 (task creation). Extend your correlation window — hunting only 1-hour windows misses this by design."}},"T1140":{"name":"Deobfuscate/Decode Files or Information","tactic":"Stealth","summary":"Payloads arrive encoded and are decoded at runtime. The decode step itself is a reliable signal because legitimate software rarely base64-decodes into execution.","detect":["certutil.exe -decode / -urlcache execution — a long-standing LOLBin decode primitive","PowerShell FromBase64String in 4104 script block logs, especially with IEX","High-entropy command-line arguments — ut_shannon_lookup with tonumber() on the shannon field"],"pivots":["CommandLine","Image","ScriptBlockText","ComputerName"],"mits":["M1040","M1038"],"subs":0,"ref":false,"start":{"win":"4688 for certutil plus 4104 script block logging. Entropy scoring on CommandLine catches the generic case — remember tonumber() on shannon."}},"T1006":{"name":"Direct Volume Access","tactic":"Stealth","summary":"Raw volume reads bypass the filesystem and its ACLs, letting an adversary copy locked files such as NTDS.dit or SAM without triggering file-access auditing.","detect":["Sysmon EID 9 RawAccessRead by non-system processes","Volume shadow copy creation (vssadmin/wmic shadowcopy) followed by file copies from the snapshot","esentutl.exe or ntdsutil.exe execution outside backup workflows"],"pivots":["Image","Device","CommandLine","ComputerName"],"mits":["M1026","M1022","M1040"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 9 is the definitive source and is low volume — enable it. Pair with 4688 for vssadmin/ntdsutil."}},"T1480":{"name":"Execution Guardrails","tactic":"Stealth","summary":"The payload only detonates on the intended target — keyed to a domain name, username, or locale — so it stays inert in your sandbox and looks benign in analysis.","detect":["Script block content referencing specific domain, hostname, or user checks before payload execution","Environment-keyed decryption routines in 4104 logs","Payloads that run on one host but not another with identical tooling"],"pivots":["ScriptBlockText","CommandLine","ComputerName","Account_Name"],"mits":["M1040"],"subs":2,"ref":false,"start":{"win":"4104 script block logging. This is largely a reason your sandbox verdicts disagree with reality — worth knowing when triaging."}},"T1211":{"name":"Exploitation for Defense Evasion","tactic":"Defense Impairment","summary":"A vulnerability in a security product is exploited to disable or blind it. Because the target is the sensor itself, the resulting silence is the signal.","detect":["Security agent services stopping or crashing (7031/7034, Application 1000) with no change ticket","Telemetry gaps — hosts that stop reporting Sysmon or EDR events while still online","Exploitation-typical child processes from security product binaries"],"pivots":["Service_Name","ParentImage","Image","ComputerName"],"mits":["M1051","M1050","M1040","M1047"],"subs":0,"ref":false,"start":{"win":"Build a heartbeat detection: alert when a host present in DHCP/AD stops sending Sysmon for N minutes. Silence detection is the only reliable approach here."}},"T1564":{"name":"Hide Artifacts","tactic":"Stealth","summary":"Files, windows, accounts, or streams are concealed so an analyst looking directly at the host sees nothing wrong. Alternate data streams and hidden accounts are the common Windows variants.","detect":["Sysmon EID 15 alternate data stream creation, especially on executables or in Downloads","Accounts created with names ending in $ or hidden from the logon UI via SpecialAccounts registry keys","attrib +h +s on directories, or files written to $Recycle.Bin and System Volume Information"],"pivots":["TargetFilename","Object_Name","New_Value","CommandLine","Account_Name"],"mits":["M1024","M1022","M1049"],"subs":14,"ref":false,"start":{"win":"Sysmon EID 15 (FileCreateStreamHash) catches ADS cheaply. SACL the SpecialAccounts\\UserList key for the hidden-account variant."}},"T1202":{"name":"Indirect Command Execution","tactic":"Stealth","summary":"Commands are launched through an intermediary (forfiles, pcalua, conhost, scriptrunner) so the parent-child chain hides the real origin.","detect":["forfiles.exe, pcalua.exe, or scriptrunner.exe spawning cmd or powershell","Unusual grandparent chains where a benign utility sits between the shell and its true parent","These utilities executing from user-writable directories"],"pivots":["Image","ParentImage","CommandLine","ProcessGuid"],"mits":["M1038","M1042"],"subs":0,"ref":false,"start":{"win":"4688 / Sysmon EID 1 with a named list of proxy utilities. Walk the ProcessGuid chain to recover the true origin."}},"T1620":{"name":"Reflective Code Loading","tactic":"Stealth","summary":"Code is loaded straight into memory with no file on disk, defeating file-based scanning entirely. Detection relies on memory-allocation and image-load telemetry.","detect":["PowerShell 4104 containing Reflection.Assembly::Load or VirtualAlloc/WriteProcessMemory patterns","Sysmon EID 8 CreateRemoteThread and EID 10 ProcessAccess with suspicious granted access masks","Processes with executable private memory but no corresponding module on disk (EDR-sourced)"],"pivots":["ScriptBlockText","SourceImage","TargetImage","GrantedAccess"],"mits":["M1040","M1038"],"subs":0,"ref":false,"start":{"win":"4104 script block logging is the cheapest source. Sysmon EID 8/10 add depth but need tuning against legitimate injectors."}},"T1014":{"name":"Rootkit","tactic":"Stealth","summary":"Kernel-level code hides processes, files, and connections from the OS itself, so anything querying from user mode returns clean results. Driver load is the last reliable observation point.","detect":["Sysmon EID 6 driver loads that are unsigned, or signed by unexpected/revoked certificates","Known vulnerable driver hashes being loaded (BYOVD)","Discrepancies between what the host reports and what the network sees — connections with no owning process"],"pivots":["ImageLoaded","Signed","Signature","Hashes","ComputerName"],"mits":["M1046","M1038","M1051","M1040"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 6 plus Microsoft vulnerable driver blocklist. Once a rootkit loads, host telemetry is suspect — pivot to network evidence."}},"T1679":{"name":"Selective Exclusion","tactic":"Stealth","summary":"Security tooling is told to ignore a specific path, process, or host. The product stays running and reports healthy, so nothing looks wrong.","detect":["Registry or policy writes adding AV/EDR exclusions (4657 on Defender Exclusions keys)","Add-MpPreference -ExclusionPath execution in 4104 or 4688","Exclusions added shortly before file writes into the excluded path"],"pivots":["Object_Name","New_Value","CommandLine","Account_Name","ComputerName"],"mits":["M1024","M1026","M1047"],"subs":0,"ref":false,"start":{"win":"SACL the Defender Exclusions registry path for 4657, and alert on Add-MpPreference. Exclusion-then-write is a near-certain intrusion sequence."}},"T1656":{"name":"Impersonation","tactic":"Stealth","summary":"The adversary poses as a trusted person or brand to get a human to act — help-desk resets, MFA approvals, payment changes. Technically light, socially effective.","detect":["Help-desk-driven password or MFA resets shortly followed by logins from new devices or geographies","Newly registered lookalike domains appearing in mail or proxy logs","Self-service MFA device registration by accounts that just contacted support"],"pivots":["Account_Name","sourceIPAddress","eventName","Logon_Type"],"mits":["M1017","M1032","M1018","M1047"],"subs":2,"ref":false,"start":{"win":"Correlate identity-provider audit logs with help-desk ticket timing. The reset-then-new-device sequence is the detection."}},"T1216":{"name":"System Script Proxy Execution","tactic":"Stealth","summary":"Signed Microsoft scripts (SyncAppvPublishingServer.vbs, pubprn.vbs) proxy execution of attacker commands past application allow-listing.","detect":["cscript/wscript executing signed system .vbs files with unusual arguments","SyncAppvPublishingServer.vbs invoked with an embedded PowerShell payload","These scripts spawning cmd/powershell children"],"pivots":["Image","CommandLine","ParentImage","ComputerName"],"mits":["M1038","M1042"],"subs":2,"ref":false,"start":{"win":"4688 command-line auditing with a small named list of proxy scripts — very low volume, high fidelity."}},"T1221":{"name":"Template Injection","tactic":"Stealth","summary":"A document fetches a remote template that carries the payload, so the delivered file itself is clean and passes attachment scanning.","detect":["Office applications making outbound HTTP requests immediately on document open (Sysmon EID 3)","Documents containing remote template references to external domains","winword.exe/excel.exe writing executables or scripts to disk shortly after launch"],"pivots":["Image","DestinationHostname","TargetFilename","ParentImage"],"mits":["M1021","M1037","M1017"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 3 filtered to Office binaries is small and effective — Office should rarely reach arbitrary external hosts."}},"T1535":{"name":"Unused/Unsupported Cloud Regions","tactic":"Stealth","summary":"Resources are created in regions you never use, where nobody is watching billing, logging, or alerting.","detect":["Any API activity in regions outside your approved list","Instance or function creation in unusual regions","CloudTrail gaps — regions where logging was never enabled"],"pivots":["awsRegion","eventName","userIdentity","sourceIPAddress"],"mits":["M1018","M1047","M1026"],"subs":0,"ref":false,"start":{"aws":"Alert on any eventName where awsRegion is outside your approved region lookup. Ensure CloudTrail is enabled in all regions — a disabled region is a blind spot by construction."}},"T1497":{"name":"Virtualization/Sandbox Evasion","tactic":"Stealth","summary":"Malware checks whether it is in a sandbox and stays dormant if so. In production this mostly matters as an artefact — the checks themselves are visible.","detect":["WMI or registry queries for VM artefacts (Win32_ComputerSystem model, VBOX/VMware registry keys)","Timing checks and long sleeps before execution (correlate with delayed child processes)","Discovery of MAC OUI ranges or CPUID-based checks in script block logs"],"pivots":["CommandLine","ScriptBlockText","Object_Name","Image"],"mits":["M1040"],"subs":3,"ref":false,"start":{"win":"4104 and 4688 command-line auditing. Low operational value in production versus malware analysis — stage it but keep expectations modest."}},"T1220":{"name":"XSL Script Processing","tactic":"Stealth","summary":"wmic and msxsl execute embedded scripts inside XSL stylesheets, bypassing allow-listing because the executing binary is a signed Microsoft tool.","detect":["wmic.exe with /format: pointing at a remote or local .xsl file","msxsl.exe execution anywhere in the estate — it is not installed by default","wmic spawning script interpreters or making outbound connections"],"pivots":["Image","CommandLine","DestinationHostname","ParentImage"],"mits":["M1038","M1042","M1040"],"subs":0,"ref":false,"start":{"win":"4688 command line matching on \"/format:\" with a URL or local path. msxsl.exe presence alone is worth an alert."}},"T1562.004":{"name":"Disable or Modify System Firewall","tactic":"Defense Impairment","summary":"Firewall rules are opened or the firewall disabled to enable lateral movement and C2. Rule additions are individually mundane, so context and scale matter.","detect":["4946/4947/4948 Windows Firewall rule added, modified, or deleted","netsh advfirewall commands, especially disabling profiles or opening 445/3389","Rule changes across many hosts in a short window — score with dc(ComputerName)"],"pivots":["Rule_Name","CommandLine","Account_Name","ComputerName"],"mits":["M1024","M1026","M1030","M1047"],"subs":3,"ref":false,"start":{"win":"Enable the MPSSVC Rule-Level Policy Change subcategory for 4946-4948 — it is off by default in many builds. 4688 catches the netsh path."}},"T1562.001":{"name":"Disable or Modify Tools","tactic":"Defense Impairment","summary":"Security tools are stopped, uninstalled, or neutered so subsequent actions go unrecorded. Usually immediately precedes the destructive or collection phase.","detect":["7036/7040 service state changes for AV/EDR services, or 7045 replacing a security service binary","net stop / sc config / taskkill targeting security product names","Defender tamper events and sudden telemetry loss from a still-online host"],"pivots":["Service_Name","CommandLine","Image","Account_Name","ComputerName"],"mits":["M1024","M1026","M1040","M1047"],"subs":6,"ref":false,"start":{"win":"7036/7040 plus 4688 command-line matching on your security vendor process names. Add a silence-detection rule as backup."}},"T1562.010":{"name":"Downgrade Attack","tactic":"Defense Impairment","summary":"The adversary forces an older, weaker version of a protocol or tool — PowerShell v2, SMBv1, NTLM instead of Kerberos — to escape modern logging and controls.","detect":["powershell.exe -version 2 execution, which bypasses script block logging entirely","4104/400 engine start events reporting an old engine version","NTLM authentication (4776) where Kerberos would be expected, or SMBv1 negotiation"],"pivots":["CommandLine","EngineVersion","Authentication_Package","ComputerName"],"mits":["M1042","M1051","M1028","M1047"],"subs":0,"ref":false,"start":{"win":"PowerShell Engine Lifecycle (400) reporting HostVersion 2.x is the cleanest catch. Remove the v2 engine feature outright where you can."}},"T1222":{"name":"File and Directory Permissions Modification","tactic":"Defense Impairment","summary":"ACLs are rewritten to grant access or to lock defenders out of their own data — the latter is common in ransomware just before encryption.","detect":["icacls / takeown / cacls execution granting Everyone or removing inherited permissions","4670 permissions changed on objects, particularly in shares or system directories","Mass ACL changes by one account across many files — a strong ransomware precursor"],"pivots":["CommandLine","Object_Name","Account_Name","ComputerName"],"mits":["M1022","M1026","M1024"],"subs":2,"ref":false,"start":{"win":"4688 for icacls/takeown plus 4670 (needs SACLs). Volume-per-account over a short window separates admin work from an attack."}},"T1578":{"name":"Modify Cloud Compute Infrastructure","tactic":"Defense Impairment","summary":"Cloud compute is manipulated — snapshots taken, instances rebuilt, images shared — to access data or evade controls without touching the running system.","detect":["CreateSnapshot followed by ModifySnapshotAttribute sharing externally","Instances launched from unexpected AMIs or with modified user data","Security group or IAM changes accompanying compute modification"],"pivots":["eventName","userIdentity","requestParameters","awsRegion"],"mits":["M1018","M1026","M1047","M1022"],"subs":5,"ref":false,"start":{"aws":"CloudTrail CreateSnapshot/ModifySnapshotAttribute/RunInstances. Snapshot-then-share-external is the clearest data theft pattern in cloud."}},"T1666":{"name":"Modify Cloud Resource Hierarchy","tactic":"Defense Impairment","summary":"Account and organisation structure is altered — accounts moved, policies detached, or new accounts created — to escape guardrails applied at the org level.","detect":["Organizations API activity: account creation, movement between OUs, or policy detachment","Service control policies modified or removed","New accounts created outside your provisioning pipeline"],"pivots":["eventName","userIdentity","requestParameters"],"mits":["M1018","M1026","M1047"],"subs":0,"ref":false,"start":{"aws":"CloudTrail organizations:* events. Any SCP detachment or account move deserves an immediate alert — these are rare and consequential."}},"T1601":{"name":"Modify System Image","tactic":"Defense Impairment","summary":"Firmware or OS images on network devices are patched to embed persistent backdoors that survive reboots and reimaging.","detect":["Image or firmware upload events on network devices","Running image hash differing from the vendor-published hash","Device reboots following unscheduled image transfers"],"pivots":["Account_Name","SourceIp","ComputerName"],"mits":["M1045","M1046","M1051","M1047"],"subs":2,"ref":false,"start":{"win":"Vendor image-verification tooling and device syslog. Verify running image hashes on a schedule."}},"T1599":{"name":"Network Boundary Bridging","tactic":"Defense Impairment","summary":"Network device controls are subverted to bridge segments, collapsing the segmentation your other controls depend on.","detect":["Configuration changes on boundary devices outside change windows","New routes, NAT rules, or tunnel interfaces appearing in device configs","Traffic observed between segments that should not communicate"],"pivots":["SourceIp","DestinationIp","Account_Name"],"mits":["M1030","M1043","M1026","M1047"],"subs":1,"ref":false,"start":{"win":"Requires network device syslog and config-diff monitoring. Windows logs will not show this — build the detection on the device side."}},"T1647":{"name":"Plist File Modification","tactic":"Defense Impairment","summary":"macOS property lists are edited to alter application behaviour or establish persistence in a way that looks like normal configuration.","detect":["Modifications to plist files in LaunchAgents or LaunchDaemons directories","defaults write commands from unexpected processes","Plists referencing binaries in user-writable paths"],"pivots":["TargetFilename","CommandLine","Image"],"mits":["M1022","M1024","M1040"],"subs":0,"ref":false,"start":"macOS endpoint telemetry required — no Windows equivalent. Stage it if you have Macs in scope, otherwise it is an honest N/A."},"T1562.003":{"name":"Prevent Command History Logging","tactic":"Defense Impairment","summary":"Shell history is disabled or cleared so the investigator cannot reconstruct what was typed. Cheap for the adversary, expensive for you at IR time.","detect":["PowerShell history file (ConsoleHost_history.txt) deleted or its path redirected","Set-PSReadlineOption -HistorySaveStyle SaveNothing in 4104 logs","Registry or profile changes disabling transcript or module logging"],"pivots":["ScriptBlockText","TargetFilename","Object_Name","Account_Name"],"mits":["M1024","M1047","M1028"],"subs":0,"ref":false,"start":{"win":"4104 script block logging catches the command even when it disables history. Ship transcripts off-host so local deletion does not matter."}},"T1207":{"name":"Rogue Domain Controller","tactic":"Defense Impairment","summary":"A fake DC is registered to inject directory changes via replication (DCShadow), bypassing normal audit trails because the change arrives as legitimate replication.","detect":["4662 with the DS-Install-Replica or replication GUIDs from a non-DC host","nTDSDSA object creation in the Configuration partition (5137/5141)","Replication traffic from a host that is not in your Domain Controllers OU"],"pivots":["Object_Name","Properties","Account_Name","ComputerName"],"mits":["M1015","M1026","M1047","M1030"],"subs":0,"ref":false,"start":{"win":"4662 with directory-object auditing on the Configuration naming context. Maintain an explicit allow-list of legitimate DC hostnames and alert on anything else replicating."}},"T1562.009":{"name":"Safe Mode Boot","tactic":"Defense Impairment","summary":"The host is rebooted into Safe Mode where most security products do not load, then ransomware runs unopposed. A well-known encryption-phase precursor.","detect":["bcdedit /set safeboot execution, or registry writes to the SafeBoot Minimal/Network keys","Service registered to start in Safe Mode via SafeBoot registry additions","Unexpected reboots (1074/6008) shortly after bcdedit activity"],"pivots":["CommandLine","Object_Name","New_Value","ComputerName"],"mits":["M1024","M1026","M1040"],"subs":0,"ref":false,"start":{"win":"4688 for bcdedit with safeboot plus 4657 on the SafeBoot keys. Very low volume — alert directly, no scoring needed."}},"T1553":{"name":"Subvert Trust Controls","tactic":"Defense Impairment","summary":"Trust mechanisms are undermined — a rogue root certificate installed, SmartScreen bypassed, or signature checks disabled — so malicious code is treated as trusted.","detect":["Root certificate installation (4657 on the Root certificate store, or certutil -addstore)","Registry writes disabling SmartScreen or attachment zone identifiers","Mark-of-the-Web removal from downloaded files (Sysmon EID 15 stream deletion)"],"pivots":["Object_Name","New_Value","CommandLine","TargetFilename"],"mits":["M1024","M1045","M1054","M1047"],"subs":6,"ref":false,"start":{"win":"SACL the certificate store keys for 4657 and alert on certutil -addstore. A new root CA on a workstation is almost never legitimate."}},"T1600":{"name":"Weaken Encryption","tactic":"Defense Impairment","summary":"Cryptographic protections are downgraded or disabled on network devices so traffic can be read or modified downstream.","detect":["Crypto configuration changes on network devices","Downgrade to weak ciphers or disabled TLS verification in device configs","Certificate or key material changes outside maintenance windows"],"pivots":["Account_Name","SourceIp","ComputerName"],"mits":["M1041","M1043","M1051","M1047"],"subs":2,"ref":false,"start":{"win":"Device syslog and configuration baselining. Out of scope for Windows Security logs."}},"T1557":{"name":"Adversary-in-the-Middle","tactic":"Credential Access","summary":"The adversary positions between two parties to capture or relay authentication — LLMNR/NBT-NS poisoning internally, or AiTM proxies for cloud sessions that defeat MFA.","detect":["Multiple hosts resolving the same name to a new, unexpected IP (LLMNR/NBT-NS poisoning)","4624 type 3 NTLM logons arriving at many hosts from a single source — relay behaviour","Cloud sign-ins where the token is used from a different ASN than the interactive login"],"pivots":["SourceIp","Logon_Type","Authentication_Package","Account_Name","ComputerName"],"mits":["M1030","M1037","M1032","M1042"],"subs":4,"ref":false,"start":{"win":"Disable LLMNR and NBT-NS, then alert on any remaining use. Relay shows as one source authenticating to many destinations — score with dc(ComputerName)."}},"T1212":{"name":"Exploitation for Credential Access","tactic":"Credential Access","summary":"A flaw in the authentication stack itself is exploited — the Kerberos or NTLM implementation, or a domain controller service — yielding credentials or tickets without touching LSASS memory.","detect":["Anomalous Kerberos errors or ticket requests (4768/4769/4771) with malformed encryption types or from unexpected hosts","LSASS or DC service crashes (Application 1000, System 7031) followed by privileged authentications","Authentications with a ticket lifetime or SID history that does not match domain policy"],"pivots":["Ticket_Encryption_Type","Service_Name","Client_Address","Account_Name"],"mits":["M1051","M1048","M1032"],"subs":0,"ref":false,"start":{"win":"4768/4769/4771 from DC Security logs, plus System 7031 for service crash correlation. Patch state matters more than detection here."}},"T1187":{"name":"Forced Authentication","tactic":"Credential Access","summary":"The victim is coerced into authenticating to an attacker-controlled host, leaking NetNTLM hashes without any malware. Often delivered via a document or shortcut referencing a UNC path.","detect":["Outbound SMB (445) or WebDAV to external or unexpected internal IPs from workstations","Sysmon EID 3 network connections to port 445 where the destination is not a known file server","4648 explicit credential use to unusual targets, and documents containing UNC references"],"pivots":["DestinationIp","DestinationPort","Image","Account_Name","ComputerName"],"mits":["M1037","M1035","M1027"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 3 filtered to port 445/139 with a destination allow-list of your file servers — small, high-signal."}},"T1606":{"name":"Forge Web Credentials","tactic":"Credential Access","summary":"SAML tokens or cookies are forged using stolen signing material, letting the adversary authenticate as anyone with no login event at the identity provider.","detect":["Sign-ins with no corresponding authentication event at the IdP — the Golden SAML tell","Token signing certificate access or export on ADFS servers","Unusual assertions: long lifetimes, unexpected issuers, or impossible attribute combinations"],"pivots":["Account_Name","sourceIPAddress","eventName","ComputerName"],"mits":["M1026","M1043","M1047","M1032"],"subs":2,"ref":false,"start":{"win":"Audit ADFS token-signing certificate access and reconcile IdP sign-in logs against application-side sessions. Gaps are the detection."}},"T1056":{"name":"Input Capture","tactic":"Credential Access","summary":"Keylogging captures credentials as the user types them, defeating hashing, vaulting, and most MFA-less controls. It is quiet on the network and usually only visible through API and driver-level artefacts.","detect":["Sysmon EID 7 loads of hooking-capable DLLs by unsigned processes, or EID 1 processes with SetWindowsHookEx behaviour","New keyboard filter drivers (7045 with a driver ImagePath, or Sysmon EID 6)","Processes writing continuously growing .txt/.log files in AppData with no legitimate owner"],"pivots":["Image","ImageLoaded","TargetFilename","Service_File_Name"],"mits":["M1040","M1026"],"subs":4,"ref":false,"start":{"win":"Sysmon EID 6 (driver load) and EID 7. 7045 catches the service/driver registration path."}},"T1111":{"name":"Multi-Factor Authentication Interception","tactic":"Credential Access","summary":"MFA material is intercepted — SIM swap, token theft, or real-time relay of one-time codes — turning MFA from a control into a formality.","detect":["Successful authentications where the MFA method changed recently for that account","Sign-ins from a new device immediately after an MFA method registration","Token replay: same session artefact from two geographies"],"pivots":["Account_Name","sourceIPAddress","eventName"],"mits":["M1032","M1017","M1018"],"subs":0,"ref":false,"start":{"win":"Identity-provider audit logs. The registration-then-immediate-use sequence is the highest-value rule."}},"T1621":{"name":"Multi-Factor Authentication Request Generation","tactic":"Credential Access","summary":"The adversary already has the password and spams push prompts until the user approves one out of fatigue. Cheap, and it works often enough to be standard tradecraft.","detect":["Multiple MFA denials for one account followed by an approval in a short window","Repeated authentication attempts from a single foreign IP against one identity","Approvals occurring outside the user’s normal working hours"],"pivots":["Account_Name","sourceIPAddress","eventName"],"mits":["M1032","M1017","M1036"],"subs":0,"ref":false,"start":{"win":"Identity-provider logs — count denials per account per 15 minutes, alert when a denial run ends in success. Move to number matching to kill the technique."}},"T1040":{"name":"Network Sniffing","tactic":"Credential Access","summary":"Traffic is captured to harvest credentials and map the network. On Windows the giveaway is promiscuous-mode tooling and driver installation.","detect":["Installation or execution of packet capture tools (wireshark, tshark, windump, pktmon)","Sysmon EID 6 npcap/WinPcap driver loads on hosts with no monitoring role","pktmon.exe usage — built in since Windows 10 and often overlooked"],"pivots":["Image","CommandLine","ImageLoaded","ComputerName"],"mits":["M1030","M1032","M1041"],"subs":0,"ref":false,"start":{"win":"4688 plus Sysmon EID 6. pktmon.exe deserves its own rule because it needs no third-party install."}},"T1528":{"name":"Steal Application Access Token","tactic":"Credential Access","summary":"OAuth tokens are harvested via consent phishing, granting persistent API access to mail and files that survives password resets and often bypasses MFA entirely.","detect":["Consent grants to newly registered or low-reputation applications, especially with mail.read or files.readwrite scopes","Token use from an IP or ASN that never appears for that identity interactively","Applications granted admin consent outside a change window"],"pivots":["eventName","userIdentity","sourceIPAddress","Account_Name"],"mits":["M1018","M1017","M1047"],"subs":0,"ref":false,"start":{"aws":"CloudTrail GetSessionToken/AssumeRoleWithWebIdentity from new source IPs.","win":"Entra ID audit logs for consent grants — forward via the Azure add-on."}},"T1649":{"name":"Steal or Forge Authentication Certificates","tactic":"Credential Access","summary":"AD CS abuse lets an adversary mint certificates that authenticate as any user, including domain admins. The resulting logons look completely legitimate, so the issuance event is the place to catch it.","detect":["Certificate issuance events (4886/4887) where the requester and the subject account differ","Requests against templates that allow subject-alternative-name specification or client authentication by low-privileged users","Certificate-based 4768 logons for accounts that have no smart-card workflow"],"pivots":["Requester","Subject","Certificate_Template","Account_Name"],"mits":["M1047","M1018","M1026"],"subs":0,"ref":false,"start":{"win":"Enable auditing on the CA (4886/4887/4899) and forward the CA Security log. Requester-not-equal-subject is the core rule."}},"T1539":{"name":"Steal Web Session Cookie","tactic":"Credential Access","summary":"Session cookies are stolen from the browser store or via AiTM proxy, letting the adversary resume an authenticated session without ever knowing the password or satisfying MFA.","detect":["Non-browser processes reading Cookies / Login Data files in browser profile directories","Same session token presenting from two distinct geographies or ASNs within a short window","Sysmon EID 11 copies of browser profile databases into staging directories"],"pivots":["TargetFilename","Image","sourceIPAddress","Account_Name"],"mits":["M1017","M1051","M1018"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 11 plus file-access auditing on browser profile paths. The impossible-travel-on-one-token pattern is the strongest cloud-side signal."}},"T1010":{"name":"Application Window Discovery","tactic":"Discovery","summary":"Open window titles are listed to see what the user is working on — banking sites, admin consoles, password managers.","detect":["API-level window enumeration by unsigned processes","Window-title capture appearing alongside keylogging artefacts","Correlate with screen capture and input capture activity"],"pivots":["Image","ScriptBlockText","ComputerName"],"mits":["M1018","M1040"],"subs":0,"ref":false,"start":"Mostly EDR-sourced; 4104 catches scripted variants. Treat as corroboration for a keylogger finding."},"T1217":{"name":"Browser Information Discovery","tactic":"Discovery","summary":"Browser history, bookmarks, and saved sites are read to map internal applications and find targets worth credential theft.","detect":["Non-browser processes reading History, Bookmarks, or Web Data files","Copies of browser profile databases into staging directories","Discovery preceding credential store access (T1555.003)"],"pivots":["TargetFilename","Image","Account_Name"],"mits":["M1018","M1022"],"subs":0,"ref":false,"start":"Sysmon EID 11 plus file access auditing on browser profile paths."},"T1580":{"name":"Cloud Infrastructure Discovery","tactic":"Discovery","summary":"Cloud compute, storage, and snapshot inventory is enumerated to find data and pivot points after credential compromise.","detect":["Describe/List API bursts from a single principal in a short window","Enumeration from an IP or region the principal has never used","Discovery immediately preceding snapshot or share actions"],"pivots":["eventName","userIdentity","sourceIPAddress","awsRegion"],"mits":["M1018","M1026","M1047"],"subs":0,"ref":false,"start":{"aws":"CloudTrail Describe*/List* burst per principal per 10 minutes. Baseline your automation principals with outputlookup, then alert on the rest."}},"T1538":{"name":"Cloud Service Dashboard","tactic":"Discovery","summary":"Console access is used to survey the environment visually, which generates far fewer API calls than scripted enumeration.","detect":["ConsoleLogin followed by broad read-only activity across services","Console access by principals that normally use API keys only","Logins from new source IPs or without MFA"],"pivots":["eventName","userIdentity","sourceIPAddress","additionalEventData"],"mits":["M1032","M1026","M1047"],"subs":0,"ref":false,"start":{"aws":"CloudTrail ConsoleLogin with MFAUsed=No is the priority alert; pair with subsequent read-only breadth."}},"T1619":{"name":"Cloud Storage Object Discovery","tactic":"Discovery","summary":"Bucket contents are enumerated to locate data worth taking — the cloud equivalent of share enumeration.","detect":["ListObjects/ListBucket bursts across many buckets by one principal","Enumeration by principals with no data-access role","Discovery immediately preceding GetObject volume spikes"],"pivots":["eventName","userIdentity","requestParameters","sourceIPAddress"],"mits":["M1018","M1022","M1047"],"subs":0,"ref":false,"start":{"aws":"S3 data events must be enabled in CloudTrail for object-level visibility — management events alone will not show this."}},"T1613":{"name":"Container and Resource Discovery","tactic":"Discovery","summary":"Cluster resources are enumerated after access to a container or service account, mapping the path to more valuable workloads.","detect":["kubectl get/list activity from unexpected service accounts","Anonymous or unauthenticated API server requests","Enumeration of secrets or configmaps across namespaces"],"pivots":["Account_Name","eventName","ComputerName"],"mits":["M1018","M1026","M1030"],"subs":0,"ref":false,"start":"Kubernetes audit logs; not visible in Windows event logs."},"T1652":{"name":"Device Driver Discovery","tactic":"Discovery","summary":"Loaded drivers are enumerated to identify security products at kernel level and to find vulnerable drivers already present for BYOVD.","detect":["driverquery.exe execution, or Get-WindowsDriver / fltmc from non-admin workflows","Enumeration followed by a driver load (Sysmon EID 6)","Queries specifically matching EDR minifilter altitudes"],"pivots":["CommandLine","Image","ImageLoaded","ComputerName"],"mits":["M1018","M1038"],"subs":0,"ref":false,"start":"4688 for driverquery/fltmc. fltmc on a workstation is unusual enough to alert directly."},"T1482":{"name":"Domain Trust Discovery","tactic":"Discovery","summary":"Trust relationships are mapped to plan cross-domain or cross-forest escalation. A strong early indicator of a targeted, AD-aware intrusion.","detect":["nltest /domain_trusts, Get-ADTrust, or dsquery trust execution","BloodHound-style LDAP collection: many distinct LDAP queries from one host in minutes","Trust enumeration by accounts with no directory-administration role"],"pivots":["CommandLine","Image","Account_Name","ComputerName"],"mits":["M1018","M1030"],"subs":0,"ref":false,"start":{"win":"4688 for the tooling plus 4662 on directory objects (needs SACL). nltest /domain_trusts is near-zero-noise outside admin tooling."}},"T1083":{"name":"File and Directory Discovery","tactic":"Discovery","summary":"The adversary maps the filesystem to find data worth stealing. Individually benign commands become meaningful in volume and sequence.","detect":["4688 dir/tree/Get-ChildItem execution with recursive flags against user data or share paths","Bursts of discovery commands from one process lineage within minutes","Enumeration immediately preceding archive creation (7z/rar) — the collection prelude"],"pivots":["CommandLine","Image","ParentImage","Account_Name"],"mits":["M1018","M1022"],"subs":0,"ref":false,"start":{"win":"4688 with command-line auditing. Alert on the burst, not the single command — count distinct discovery commands per ProcessGuid."}},"T1615":{"name":"Group Policy Discovery","tactic":"Discovery","summary":"GPO enumeration reveals security configuration, delegation gaps, and paths to domain-wide execution — often a precursor to GPO-based deployment of ransomware.","detect":["gpresult, Get-GPO, or SYSVOL browsing by non-admin accounts","LDAP queries for groupPolicyContainer objects","GPO reads followed by GPO modification (5136 directory service changes)"],"pivots":["CommandLine","Object_Name","Account_Name","ComputerName"],"mits":["M1018","M1030"],"subs":0,"ref":false,"start":{"win":"4688 plus 5136 for the follow-on modification. GPO write by a non-admin is the escalation you actually care about."}},"T1680":{"name":"Local Storage Discovery","tactic":"Discovery","summary":"Local drives and volumes are enumerated to find data and to identify targets for encryption or wiping.","detect":["wmic logicaldisk, fsutil, or Get-Volume execution","Enumeration immediately preceding mass file access or encryption","Drive enumeration combined with share discovery in one lineage"],"pivots":["CommandLine","Image","ProcessGuid","ComputerName"],"mits":["M1018"],"subs":0,"ref":false,"start":"4688 command-line auditing; strongest as part of a discovery-burst correlation."},"T1654":{"name":"Log Enumeration","tactic":"Discovery","summary":"The adversary reads logs to learn what is being recorded and who is watching — reconnaissance against your detection capability itself, usually just before evasion or clearing.","detect":["wevtutil el / Get-WinEvent / Get-EventLog execution by non-admin workflows","Log enumeration immediately followed by 1102 or 4719 audit-policy change","Queries specifically targeting Security or Sysmon channels"],"pivots":["CommandLine","Image","Account_Name","ComputerName"],"mits":["M1018","M1022","M1029"],"subs":0,"ref":false,"start":{"win":"4688 command-line auditing. Chain to 1102 and 4719 — enumeration-then-clearing is a very strong sequence."}},"T1135":{"name":"Network Share Discovery","tactic":"Discovery","summary":"Shares are enumerated to locate data and lateral movement targets. It is the standard precursor to both collection and ransomware spread.","detect":["net view / net share / Get-SmbShare execution, particularly from workstations","5140 share access to many distinct shares by one account in a short window","Enumeration followed by write access to executables on those shares"],"pivots":["CommandLine","Share_Name","Account_Name","ComputerName"],"mits":["M1018","M1022","M1049"],"subs":0,"ref":false,"start":{"win":"4688 for the commands plus 5140 for the resulting access. dc(Share_Name) per account is the strongest scoring signal."}},"T1201":{"name":"Password Policy Discovery","tactic":"Discovery","summary":"Lockout thresholds and complexity rules are read so password spraying can stay just under the threshold.","detect":["net accounts, Get-ADDefaultDomainPasswordPolicy, or net accounts /domain execution","Policy discovery immediately followed by a rise in 4771/4625 failures","LDAP queries for domain password policy attributes"],"pivots":["CommandLine","Image","Account_Name","ComputerName"],"mits":["M1018","M1027"],"subs":0,"ref":false,"start":"4688 then correlate to 4625/4771 volume. Discovery-then-spray is a tight, high-confidence sequence."},"T1120":{"name":"Peripheral Device Discovery","tactic":"Discovery","summary":"Attached devices are enumerated to find removable media for staging, exfiltration, or air-gap bridging.","detect":["fsutil fsinfo drives, wmic diskdrive, or Get-PnpDevice execution","Discovery immediately followed by writes to removable media","USB device insertion events correlated with enumeration"],"pivots":["CommandLine","Image","TargetFilename","ComputerName"],"mits":["M1018","M1042"],"subs":0,"ref":false,"start":"4688 plus Sysmon EID 11 for follow-on writes to removable drives."},"T1057":{"name":"Process Discovery","tactic":"Discovery","summary":"Running processes are listed to find security tooling and interesting targets. Frequently the step immediately before defence evasion.","detect":["tasklist / Get-Process / wmic process execution, especially filtered for AV or EDR product names","Process enumeration followed within minutes by attempts to stop a security service","Discovery from a process lineage that also performed file or account enumeration"],"pivots":["CommandLine","Image","ParentImage","ProcessGuid"],"mits":["M1018"],"subs":0,"ref":false,"start":{"win":"4688 command-line auditing. Correlate to 7036/7045 service changes to catch the discovery-then-disable pattern."}},"T1012":{"name":"Query Registry","tactic":"Discovery","summary":"The registry is read to find configuration, credentials, and installed software. Individually noisy, meaningful in bursts and against sensitive keys.","detect":["reg query against credential-bearing or security-config keys","Sysmon EID 12 registry key access on Run keys, LSA, or Defender settings","Registry enumeration combined with other discovery in one lineage"],"pivots":["CommandLine","Object_Name","Image","ProcessGuid"],"mits":["M1018","M1024"],"subs":0,"ref":false,"start":"4688 for reg.exe. Sysmon EID 12 is high volume — scope it to a curated key list only."},"T1518":{"name":"Software Discovery","tactic":"Discovery","summary":"Installed software and, critically, security products are enumerated so the adversary can pick evasion and exploitation paths.","detect":["wmic product get, Get-WmiObject Win32_Product, or registry Uninstall key enumeration","Queries naming AV/EDR vendors specifically — a strong intent signal","Discovery preceding service-stop or driver-load attempts"],"pivots":["CommandLine","Image","Object_Name","Account_Name"],"mits":["M1018","M1047"],"subs":2,"ref":false,"start":{"win":"4688 command line plus 4657 on the Uninstall registry path. Vendor-name string matching gives the sharpest rule."}},"T1614":{"name":"System Location Discovery","tactic":"Discovery","summary":"Locale and region are checked, commonly as a guardrail so the payload skips certain countries or targets only a chosen region.","detect":["Locale/keyboard-layout queries via GetLocaleInfo or registry reads","Geolocation API calls from unexpected processes","Locale checks preceding conditional execution"],"pivots":["CommandLine","Object_Name","Image"],"mits":["M1018"],"subs":1,"ref":false,"start":"4688 and 4104. Primarily useful as evidence of targeting during analysis."},"T1016":{"name":"System Network Configuration Discovery","tactic":"Discovery","summary":"Host network configuration is read to understand the environment and plan movement. Among the first commands run after a foothold.","detect":["ipconfig /all, route print, arp -a, netsh interface show execution","netsh wlan show profiles key=clear — Wi-Fi credential harvesting","Multiple network discovery commands within minutes of a new process lineage"],"pivots":["CommandLine","Image","ParentImage","ComputerName"],"mits":["M1018"],"subs":2,"ref":false,"start":"4688 command-line auditing. The netsh wlan variant is worth its own higher-severity rule."},"T1049":{"name":"System Network Connections Discovery","tactic":"Discovery","summary":"Active connections are listed to map peers and find live sessions to hijack or pivot toward.","detect":["netstat, Get-NetTCPConnection, or net use execution from non-admin accounts","Combined with 4688 discovery bursts across a single lineage","Enumeration on servers where interactive admin activity is unexpected"],"pivots":["CommandLine","Image","Account_Name","ComputerName"],"mits":["M1018"],"subs":0,"ref":false,"start":{"win":"4688 command-line auditing; low volume on workstations, treat servers as higher signal."}},"T1033":{"name":"System Owner/User Discovery","tactic":"Discovery","summary":"The adversary confirms whose context they hold and who else is logged on, deciding whether to escalate or move.","detect":["whoami, query user, quser, or Get-WmiObject Win32_LoggedOnUser execution","whoami /priv or /groups — checking for exploitable privileges","Executed within seconds of initial access as part of an orientation burst"],"pivots":["CommandLine","Image","Account_Name","ProcessGuid"],"mits":["M1018"],"subs":0,"ref":false,"start":"4688. whoami /priv is a stronger signal than bare whoami — separate them by severity."},"T1007":{"name":"System Service Discovery","tactic":"Discovery","summary":"Services are enumerated to find security products, backup agents, and privileged service accounts worth targeting.","detect":["sc query / Get-Service / net start execution, particularly filtered for vendor names","Service enumeration immediately preceding a service-stop attempt","Discovery bursts from a single process lineage"],"pivots":["CommandLine","Image","ParentImage","ComputerName"],"mits":["M1018"],"subs":0,"ref":false,"start":"4688 command-line auditing; chain to 7036/7040 to catch enumerate-then-disable."},"T1124":{"name":"System Time Discovery","tactic":"Discovery","summary":"System time and timezone are read, often to schedule payloads for a specific local moment or to fingerprint the target region.","detect":["net time, w32tm, or Get-Date execution in an automated context","Time discovery preceding scheduled task creation","Timezone queries as part of a guardrail check"],"pivots":["CommandLine","Image","ProcessGuid"],"mits":["M1018"],"subs":0,"ref":false,"start":"4688. Low value alone — use it as a corroborating element in a discovery-burst rule."},"T1673":{"name":"Virtual Machine Discovery","tactic":"Discovery","summary":"Hypervisor-hosted VMs are enumerated, typically as a precursor to mass encryption of virtual disks.","detect":["esxcli/vim-cmd VM listing, or Get-VM on Hyper-V hosts","Enumeration on a hypervisor followed by VM power-off commands","Access to datastore paths by unexpected accounts"],"pivots":["CommandLine","Image","Account_Name","ComputerName"],"mits":["M1018","M1026","M1030"],"subs":0,"ref":false,"start":"Hypervisor logs plus 4688 on Hyper-V hosts. Enumerate-then-power-off is the ransomware pattern — alert on the pair."},"T1210":{"name":"Exploitation of Remote Services","tactic":"Lateral Movement","summary":"An unpatched internal service is exploited to move host to host without credentials. Because no logon occurs, credential-centric lateral movement detection misses it entirely.","detect":["Service crash then anomalous child process on the same host (System 7031/7034 followed by 4688)","Sysmon EID 3 inbound connections to SMB/RPC/RDP from hosts that have never talked to that peer before","Exploit-typical parents: services.exe, spoolsv.exe, or lsass.exe spawning cmd or powershell"],"pivots":["ParentImage","Image","SourceIp","DestinationPort","ComputerName"],"mits":["M1051","M1030","M1035"],"subs":0,"ref":false,"start":{"win":"4688 parent-child anomalies plus Sysmon EID 3. Pair with dc(ComputerName) scoring — exploitation waves hit many hosts fast."}},"T1534":{"name":"Internal Spearphishing","tactic":"Lateral Movement","summary":"A compromised internal mailbox phishes colleagues. The mail passes SPF/DKIM and arrives from a trusted coworker, so user reporting rates collapse and gateway controls do not apply.","detect":["Internal senders mailing unusually large recipient sets in a short window","Mailbox rules created that auto-delete replies or move messages to obscure folders","Links in internal mail pointing to newly registered domains or credential-harvest pages"],"pivots":["Account_Name","sourceIPAddress","eventName"],"mits":["M1017","M1054","M1018"],"subs":0,"ref":false,"start":{"win":"Requires mail-platform audit logs (Exchange/Defender). Correlate with 4624 for the sending account to find the initial compromise."}},"T1563":{"name":"Remote Service Session Hijacking","tactic":"Lateral Movement","summary":"An existing RDP or SSH session is taken over, so the adversary inherits an already-authenticated privileged session without generating a new credential use.","detect":["4778/4779 session reconnect events from a different source than the original session","tscon.exe execution, especially from SYSTEM context — the classic RDP hijack primitive","Session reconnects where the Client_Name differs from the session originator"],"pivots":["Session_Name","Client_Name","Client_Address","Account_Name","Image"],"mits":["M1030","M1032","M1026"],"subs":2,"ref":false,"start":{"win":"4778/4779 plus 4688 for tscon.exe. tscon from SYSTEM is near-zero false positive — alert on it directly."}},"T1080":{"name":"Taint Shared Content","tactic":"Lateral Movement","summary":"Files on a network share are backdoored so that other users execute them, spreading the compromise through normal business workflow rather than an active push.","detect":["5145 write access to executables, scripts, or .lnk files on shares by accounts that normally only read","Sysmon EID 11 modification of .exe/.dll/.lnk on mapped drives","A single account modifying many files across a share in a short window"],"pivots":["Share_Name","Relative_Target_Name","Accesses","Account_Name","ComputerName"],"mits":["M1049","M1050","M1022"],"subs":0,"ref":false,"start":{"win":"5145 (detailed file share) must be explicitly enabled — it is off by default and is the key event here. Filter to write access on executable extensions."}},"T1123":{"name":"Audio Capture","tactic":"Collection","summary":"The microphone is used to record conversations, capturing information that never touches a keyboard or a file.","detect":["Processes accessing audio capture devices without a conferencing role","Audio files accumulating in AppData or Temp","Microphone access by unsigned binaries"],"pivots":["Image","TargetFilename","ComputerName"],"mits":["M1040","M1042"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 11 for audio file writes; device access is EDR-sourced. Correlate with other collection techniques on the same host."}},"T1119":{"name":"Automated Collection","tactic":"Collection","summary":"Scripted collection sweeps the host for files matching patterns, gathering far more than a human would and much faster.","detect":["Scripts iterating filesystems with extension or keyword filters (4104)","High-rate file read events by a single process across many directories","Collection scripts followed immediately by archive creation"],"pivots":["ScriptBlockText","Image","TargetFilename","ProcessGuid"],"mits":["M1057","M1022","M1047"],"subs":0,"ref":false,"start":{"win":"4104 script block logging plus Sysmon EID 11. Rate-based rules work well — normal users do not touch hundreds of files per minute."}},"T1185":{"name":"Browser Session Hijacking","tactic":"Collection","summary":"The adversary rides an authenticated browser session, acting as the user inside applications without ever handling credentials.","detect":["Browsers launched with remote debugging ports enabled","Extensions or processes attaching to browser debug interfaces","Application actions from a session with no corresponding fresh authentication"],"pivots":["CommandLine","Image","DestinationPort","Account_Name"],"mits":["M1040","M1018","M1021"],"subs":0,"ref":false,"start":{"win":"4688 command-line matching on --remote-debugging-port is a precise, low-noise rule."}},"T1115":{"name":"Clipboard Data","tactic":"Collection","summary":"The clipboard is monitored to capture passwords copied out of password managers — a direct bypass of vault protections.","detect":["Processes registering clipboard listeners (AddClipboardFormatListener) unexpectedly","Get-Clipboard usage in script block logs","Clipboard access correlated with password manager process activity"],"pivots":["ScriptBlockText","Image","ComputerName"],"mits":["M1040"],"subs":0,"ref":false,"start":{"win":"4104 catches the scripted case; the API case is EDR-sourced. Correlate with password manager usage for context."}},"T1602":{"name":"Data from Configuration Repository","tactic":"Collection","summary":"Network device configurations are pulled via SNMP or management interfaces, revealing topology, ACLs, and often credential hashes.","detect":["SNMP walk activity, especially with default or guessed community strings","Config retrieval from devices by unexpected sources","Bulk device queries from a single host"],"pivots":["SourceIp","DestinationIp","ComputerName"],"mits":["M1030","M1027","M1032","M1043"],"subs":2,"ref":false,"start":"Network device syslog and flow data. SNMP from a workstation is almost always worth investigating."},"T1213":{"name":"Data from Information Repositories","tactic":"Collection","summary":"Confluence, SharePoint, code repos, and ticketing systems are mined — often the fastest route to credentials and architecture knowledge.","detect":["Bulk document access or download by one identity in a short window","Searches for credential-suggestive keywords (password, secret, key) in repositories","Access to spaces or repos outside the user’s normal scope"],"pivots":["Account_Name","eventName","sourceIPAddress"],"mits":["M1018","M1022","M1047","M1057"],"subs":6,"ref":false,"start":"Application audit logs required. Rate-based download rules plus credential-keyword search alerts give the best coverage."},"T1025":{"name":"Data from Removable Media","tactic":"Collection","summary":"Files are collected from attached USB and external drives, which often hold unmanaged copies of sensitive data.","detect":["Processes reading broadly from removable drive letters","Archive creation sourced from removable media paths","USB insertion followed immediately by bulk reads"],"pivots":["TargetFilename","Image","ComputerName"],"mits":["M1057","M1022","M1042"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 11 plus removable-device events. Device control policy is the more effective lever than detection."}},"T1074":{"name":"Data Staged","tactic":"Collection","summary":"Data is gathered into one location before exfiltration. Staging is often the last quiet moment before the loud part, which makes it valuable to catch.","detect":["Archive creation (7z, rar, zip) of large or many files in Temp, ProgramData, or Public","Sysmon EID 11 rapid file writes into a single directory from many sources","Staging directory growth followed by outbound transfer"],"pivots":["Image","TargetFilename","CommandLine","ComputerName"],"mits":["M1057","M1022","M1047"],"subs":2,"ref":false,"start":{"win":"4688 for archive utilities plus Sysmon EID 11. Archive tooling running outside IT workflows is a strong standalone signal."}},"T1114":{"name":"Email Collection","tactic":"Collection","summary":"Mailboxes are harvested for credentials, contracts, and intelligence. Forwarding rules make it continuous and survive the loss of the session.","detect":["Auto-forwarding rules to external domains created on any mailbox","PST/OST export or eDiscovery searches by unexpected accounts","Mass mail access by one identity outside normal patterns"],"pivots":["Account_Name","eventName","sourceIPAddress"],"mits":["M1018","M1047","M1054","M1057"],"subs":3,"ref":false,"start":"Mail platform audit logs are required. The external-forwarding rule is the single highest-value alert here."},"T1113":{"name":"Screen Capture","tactic":"Collection","summary":"Screenshots capture what controls cannot — data on screen, MFA prompts, and admin consoles — with a small on-disk footprint.","detect":["Processes writing image files periodically to AppData or Temp","Screen capture API usage by unsigned processes","Image files accumulating with timestamp-based names"],"pivots":["TargetFilename","Image","ComputerName"],"mits":["M1040","M1057"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 11 filtered to image extensions in user-writable paths, scored by write frequency per process."}},"T1125":{"name":"Video Capture","tactic":"Collection","summary":"Webcam or screen video is recorded, capturing the physical environment and on-screen activity over time.","detect":["Camera device access by processes with no conferencing purpose","Video files written to user-writable directories","Capture activity correlated with screen capture and keylogging"],"pivots":["Image","TargetFilename","ComputerName"],"mits":["M1040","M1042"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 11 for video file writes plus EDR device-access telemetry. Rarely standalone — usually part of a wider surveillance implant."}},"T1092":{"name":"Communication Through Removable Media","tactic":"Command and Control","summary":"Air-gapped systems are controlled by passing commands on removable media, so there is no network traffic at all.","detect":["Executable or script writes to removable media on hosts that bridge networks","USB device usage on segregated systems","Files with encoded content appearing on removable drives"],"pivots":["TargetFilename","Image","ComputerName"],"mits":["M1042","M1030","M1049"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 11 on removable paths plus device control logging. Detection is weak by design — device policy is the real control."}},"T1132":{"name":"Data Encoding","tactic":"Command and Control","summary":"C2 data is encoded (base64, hex, custom) so simple string matching on payloads fails.","detect":["High-entropy strings in URLs or headers — ut_shannon_lookup with tonumber() on shannon","Long base64-like path or query segments in proxy logs","Encoded blobs appearing in DNS query names"],"pivots":["DestinationIp","DestinationHostname","DestinationPort","Image","ComputerName"],"mits":["M1031","M1037"],"subs":2,"ref":false,"start":{"win":"Proxy log entropy scoring is the practical approach. Remember tonumber() on the shannon field before thresholding."}},"T1001":{"name":"Data Obfuscation","tactic":"Command and Control","summary":"C2 content is disguised inside otherwise normal traffic — junk padding, steganography, or protocol impersonation — so payload inspection fails while the channel stays open.","detect":["Traffic on a known port whose content does not match the expected protocol","Beacon-like regular intervals with jittered payload sizes","Images or documents transferred with anomalous size-to-content ratios"],"pivots":["DestinationIp","DestinationHostname","DestinationPort","Image","ComputerName"],"mits":["M1031","M1037"],"subs":3,"ref":false,"start":{"win":"Sysmon EID 3 for the connection plus proxy logs. Periodicity analysis over destination-per-host beats content inspection here."}},"T1568":{"name":"Dynamic Resolution","tactic":"Command and Control","summary":"C2 destinations are computed at runtime via DGA or fast-flux, so static IP and domain blocking cannot keep up.","detect":["Bursts of NXDOMAIN responses from one host — the classic DGA signature","High-entropy domain names in DNS logs","Rapidly changing IP answers for a single domain"],"pivots":["query","DestinationHostname","ComputerName","Image"],"mits":["M1031","M1037","M1021"],"subs":3,"ref":false,"start":{"win":"DNS logs are essential. NXDOMAIN count per host per 10 minutes is the single most effective DGA rule."}},"T1573":{"name":"Encrypted Channel","tactic":"Command and Control","summary":"C2 is encrypted, often with attacker-supplied keys or self-signed certificates, so content inspection is impossible and metadata becomes the only evidence.","detect":["Self-signed or recently issued certificates on outbound TLS from workstations","JA3/JA3S fingerprints not matching known-good client software","Long-lived TLS sessions with regular small payloads"],"pivots":["DestinationIp","DestinationHostname","DestinationPort","Image","ComputerName"],"mits":["M1031","M1037"],"subs":2,"ref":false,"start":{"win":"TLS metadata from your proxy or network sensor. Certificate age and JA3 are more useful than anything host-side."}},"T1008":{"name":"Fallback Channels","tactic":"Command and Control","summary":"A secondary C2 path activates when the primary is blocked, so a single block looks like success while the adversary keeps control.","detect":["A host contacting a new external destination shortly after an outbound block","Multiple distinct external destinations from one process over time","Protocol switching (HTTPS to DNS) by the same process"],"pivots":["DestinationIp","DestinationHostname","DestinationPort","Image","ComputerName"],"mits":["M1031","M1037"],"subs":0,"ref":false,"start":{"win":"Correlate firewall/proxy denies with the next new destination from the same host within minutes. That sequence is the detection."}},"T1665":{"name":"Hide Infrastructure","tactic":"Command and Control","summary":"C2 infrastructure is concealed behind CDNs, domain fronting, or bulletproof hosting so takedown and attribution both fail.","detect":["TLS SNI not matching the HTTP Host header — the domain fronting tell","Traffic to CDN edges with unusual paths from non-browser processes","Destinations resolving to hosting ranges with poor reputation"],"pivots":["DestinationIp","DestinationHostname","DestinationPort","Image","ComputerName"],"mits":["M1031","M1037","M1021"],"subs":0,"ref":false,"start":{"win":"Requires proxy or TLS inspection metadata. SNI-versus-Host mismatch is the definitive fronting detection."}},"T1104":{"name":"Multi-Stage Channels","tactic":"Command and Control","summary":"Separate channels are used for staging and for control, so blocking the loader does not remove the implant.","detect":["A host contacting one external destination for download then a different one for persistent beaconing","Short-lived first-stage connection followed by long-lived second","Distinct processes handling each phase"],"pivots":["DestinationIp","DestinationHostname","DestinationPort","Image","ComputerName"],"mits":["M1031","M1037"],"subs":0,"ref":false,"start":{"win":"Chain Sysmon EID 3 by ComputerName over an hour and look for the download-then-beacon shape."}},"T1095":{"name":"Non-Application Layer Protocol","tactic":"Command and Control","summary":"C2 runs over ICMP or raw transport protocols that many inspection stacks ignore entirely.","detect":["ICMP with unusually large or variable payloads","Raw socket usage by user-mode processes","Sustained ICMP volume between one internal host and one external IP"],"pivots":["DestinationIp","DestinationHostname","DestinationPort","Image","ComputerName"],"mits":["M1031","M1037","M1030"],"subs":0,"ref":false,"start":{"win":"Requires network telemetry — Sysmon EID 3 does not cover ICMP. Alert on ICMP payload size and volume at the perimeter."}},"T1571":{"name":"Non-Standard Port","tactic":"Command and Control","summary":"A standard protocol runs on an unexpected port to slip past port-based controls and analyst assumptions.","detect":["HTTPS or HTTP on ports other than 443/80","Sysmon EID 3 outbound connections to uncommon high ports from user processes","Protocol-port mismatch reported by network inspection"],"pivots":["DestinationIp","DestinationHostname","DestinationPort","Image","ComputerName"],"mits":["M1031","M1037","M1030"],"subs":0,"ref":false,"start":{"win":"Sysmon EID 3 with an allow-list of expected outbound ports per host role. Small allow-list, high signal."}},"T1219":{"name":"Remote Access Tools","tactic":"Command and Control","summary":"Legitimate remote-access software (AnyDesk, TeamViewer, ScreenConnect) is installed as C2 — signed, trusted, and often already allowed.","detect":["Installation or execution of RMM tools not in your approved list","RMM binaries running from Temp or AppData rather than Program Files","New RMM tooling appearing on several hosts — score by dc(ComputerName)"],"pivots":["Image","CommandLine","DestinationHostname","ComputerName"],"mits":["M1038","M1042","M1037","M1033"],"subs":3,"ref":false,"start":{"win":"4688 with a maintained allow-list of sanctioned RMM tools. Unapproved RMM is one of the highest-yield ransomware precursors."}},"T1102":{"name":"Web Service","tactic":"Command and Control","summary":"Legitimate services (GitHub, Pastebin, cloud storage, social platforms) carry C2, so traffic goes to a reputable domain your controls trust.","detect":["Non-browser processes connecting to code-sharing or paste services","Regular polling of a single URL by a background process","Access to raw content endpoints (raw.githubusercontent, pastebin raw)"],"pivots":["DestinationIp","DestinationHostname","DestinationPort","Image","ComputerName"],"mits":["M1021","M1031","M1037"],"subs":3,"ref":false,"start":{"win":"Sysmon EID 3 plus proxy logs, filtered to non-browser Image values. That filter alone removes most of the noise."}},"T1020":{"name":"Automated Exfiltration","tactic":"Exfiltration","summary":"Collection and transfer are scripted so data leaves continuously with no operator present, often on a schedule.","detect":["Scheduled tasks that invoke network transfer utilities","Regular outbound transfers of consistent size at consistent times","Scripts combining file enumeration with upload calls (4104)"],"pivots":["CommandLine","ScriptBlockText","DestinationHostname","ComputerName"],"mits":["M1057","M1037","M1047"],"subs":1,"ref":false,"start":{"win":"4698 task creation plus 4104. Periodicity in outbound byte counts per host is the network-side confirmation."}},"T1030":{"name":"Data Transfer Size Limits","tactic":"Exfiltration","summary":"Data is split into small chunks to stay under DLP and volumetric alert thresholds — deliberately engineered to defeat size-based rules.","detect":["Many uniform-sized outbound transfers to one destination","Sustained low-rate transfer totalling large volume over hours","Consistent payload sizes suggesting a fixed chunk parameter"],"pivots":["DestinationIp","DestinationHostname","ComputerName"],"mits":["M1057","M1037","M1031"],"subs":0,"ref":false,"start":{"win":"Aggregate bytes per source-destination pair over 24 hours rather than per session. Chunking beats per-session thresholds by design."}},"T1011":{"name":"Exfiltration Over Other Network Medium","tactic":"Exfiltration","summary":"Data leaves over a path your monitoring does not cover — Bluetooth, cellular, or a second NIC — bypassing the perimeter entirely.","detect":["Hosts with unexpected active network adapters","Bluetooth or tethering activity on managed endpoints","Data volume leaving a host that does not correlate with monitored traffic"],"pivots":["Image","CommandLine","ComputerName"],"mits":["M1042","M1030","M1057"],"subs":1,"ref":false,"start":{"win":"Adapter inventory plus device control. Alert on new network adapters appearing on managed hosts."}},"T1052":{"name":"Exfiltration Over Physical Medium","tactic":"Exfiltration","summary":"Data walks out on a USB drive. No network control sees it, and it remains one of the most effective exfiltration routes.","detect":["Bulk file copies to removable drive letters","USB insertion followed by sustained write volume","Archive files written directly to removable media"],"pivots":["TargetFilename","Image","ComputerName"],"mits":["M1042","M1057","M1022"],"subs":1,"ref":false,"start":{"win":"Sysmon EID 11 on removable paths plus removable-device events. Device control policy is the effective mitigation."}},"T1029":{"name":"Scheduled Transfer","tactic":"Exfiltration","summary":"Exfiltration is timed to blend with backup windows or quiet hours when nobody is watching dashboards.","detect":["Outbound data spikes at consistent off-hours times","Scheduled tasks with network actions running outside business hours","Transfers aligned suspiciously well with legitimate backup schedules"],"pivots":["CommandLine","DestinationIp","ComputerName"],"mits":["M1057","M1037","M1047"],"subs":0,"ref":false,"start":{"win":"Baseline outbound bytes per host per hour, then alert on off-hours deviation. 4698 catches the scheduling side."}},"T1537":{"name":"Transfer Data to Cloud Account","tactic":"Exfiltration","summary":"Data is copied to an attacker-controlled cloud account using the provider’s own replication features, so it never crosses your perimeter as recognisable exfiltration.","detect":["Snapshot or bucket sharing with external account IDs","ModifySnapshotAttribute or PutBucketPolicy granting outside principals","Cross-account replication configured outside change control"],"pivots":["eventName","userIdentity","requestParameters","recipientAccountId"],"mits":["M1018","M1022","M1047","M1057"],"subs":0,"ref":false,"start":{"aws":"CloudTrail ModifySnapshotAttribute, PutBucketPolicy, and PutBucketReplication with an external account ID. Maintain an allow-list of your own account IDs and alert on anything else."}},"T1485":{"name":"Data Destruction","tactic":"Impact","summary":"Files are overwritten or deleted irrecoverably to deny access, often as the destructive finale of an intrusion or to cover forensic tracks.","detect":["Mass file deletion or overwrite by a single process (Sysmon EID 23/26 file delete events)","Execution of sdelete, cipher /w, or format from non-admin workflows","Volume of 4663 delete-access events spiking far above baseline for an account"],"pivots":["Image","TargetFilename","Account_Name","ComputerName","Accesses"],"mits":["M1053","M1029","M1022"],"subs":1,"ref":false,"start":{"win":"Sysmon EID 23/26 (FileDelete) is the cleanest source. 4663 works but needs SACLs and is heavy."}},"T1565":{"name":"Data Manipulation","tactic":"Impact","summary":"Data is altered rather than destroyed, undermining integrity and decision-making. Harder to spot than deletion because systems keep working.","detect":["Unexpected modifications to database or financial records outside application workflows","Direct file edits to data stores by non-application processes","Checksum or reconciliation mismatches in business data"],"pivots":["TargetFilename","Image","Account_Name","ComputerName"],"mits":["M1053","M1022","M1041","M1047"],"subs":3,"ref":false,"start":{"win":"Application-level auditing plus Sysmon EID 11 on data directories. Reconciliation controls detect this better than log analysis."}},"T1491":{"name":"Defacement","tactic":"Impact","summary":"Visible content is altered to intimidate, claim credit, or mislead. Internal defacement usually means the adversary no longer cares about stealth.","detect":["Web root file modifications outside deployment windows","Wallpaper or logon banner registry changes across many hosts","Sysmon EID 11 writes to index files or image assets by unexpected processes"],"pivots":["TargetFilename","Object_Name","New_Value","ComputerName"],"mits":["M1053","M1022","M1045"],"subs":2,"ref":false,"start":{"win":"Sysmon EID 11 scoped to web roots, plus 4657 on wallpaper/legal-notice keys. dc(ComputerName) catches the mass-internal variant."}},"T1561":{"name":"Disk Wipe","tactic":"Impact","summary":"The disk structure or contents are destroyed directly, rendering the host unbootable. This is beyond file deletion — recovery requires reimaging, and it usually runs at the very end of an intrusion.","detect":["Raw disk handle opens (\\\\.\\PhysicalDrive) by non-system processes — Sysmon EID 9 RawAccessRead","Execution of diskpart, dd, or unknown binaries immediately before mass host unavailability","Multiple hosts going offline within a short window — correlate 6008 unexpected shutdowns by dc(ComputerName)"],"pivots":["Image","Device","ComputerName","Account_Name"],"mits":["M1053","M1018","M1026"],"subs":2,"ref":false,"start":{"win":"Sysmon EID 9 (RawAccessRead) is the distinctive source and is low volume — enable it."}},"T1667":{"name":"Email Bombing","tactic":"Impact","summary":"A mailbox is flooded to bury a real notification — often a fraud confirmation or security alert the victim must not see.","detect":["Sudden inbound mail volume spike to a single mailbox","Mass subscription confirmations arriving together","Flood coinciding with a financial transaction or password reset"],"pivots":["Account_Name","eventName","sourceIPAddress"],"mits":["M1054","M1017","M1047"],"subs":0,"ref":false,"start":"Mail platform telemetry. Treat a mail bomb as an active-fraud indicator and check what it is hiding."},"T1499":{"name":"Endpoint Denial of Service","tactic":"Impact","summary":"A host or application is exhausted so it cannot serve legitimate users. Often a diversion masking a concurrent intrusion elsewhere.","detect":["Sustained resource exhaustion (4625 floods, application pool recycling, service restarts 7031/7034)","High connection counts from few sources to a single service port","Application crash loops in the Application log during a traffic spike"],"pivots":["SourceIp","DestinationPort","Service_Name","ComputerName"],"mits":["M1037","M1030"],"subs":4,"ref":false,"start":{"win":"System 7031/7034 for service restarts plus perimeter flow data. Treat a DoS as a possible cover event and hunt in parallel."}},"T1657":{"name":"Financial Theft","tactic":"Impact","summary":"The objective is money — BEC, fraudulent payment redirection, or extortion. The technical footprint is small; the signal lives in mailbox manipulation and identity anomalies.","detect":["Inbox rules that hide or auto-delete messages containing finance keywords (invoice, payment, wire)","Mail-forwarding rules to external domains created by finance-adjacent accounts","Logins to finance mailboxes from new geographies followed immediately by rule creation"],"pivots":["Account_Name","sourceIPAddress","eventName"],"mits":["M1017","M1018","M1054"],"subs":0,"ref":false,"start":{"win":"Mail-platform audit logs are required. The keyword-hiding inbox rule is the single highest-fidelity BEC indicator."}},"T1495":{"name":"Firmware Corruption","tactic":"Impact","summary":"Firmware is overwritten to brick hardware or persist below the OS. Almost nothing in Windows event logging sees this directly — detection depends on vendor and boot integrity telemetry.","detect":["Firmware update utilities executing outside a maintenance window","Secure Boot or measured-boot integrity failures reported at startup","Hosts failing to boot after a confirmed intrusion — treat as firmware until disproven"],"pivots":["Image","CommandLine","ComputerName"],"mits":["M1046","M1051","M1026"],"subs":0,"ref":false,"start":{"win":"Rely on vendor firmware-integrity telemetry and TPM/measured boot attestation; Windows Security logs will not cover this."}},"T1498":{"name":"Network Denial of Service","tactic":"Impact","summary":"Network capacity is saturated to deny access. Frequently a smokescreen for concurrent intrusion activity.","detect":["Traffic volume spikes far beyond baseline at the perimeter","High connection rates from many sources to one service","Upstream provider or CDN alerts"],"pivots":["SourceIp","DestinationIp","DestinationPort"],"mits":["M1037","M1030"],"subs":2,"ref":false,"start":"Perimeter flow data and provider telemetry. Always hunt in parallel — DoS is often cover for something quieter."},"T1496":{"name":"Resource Hijacking","tactic":"Impact","summary":"Compute is stolen for cryptomining or proxyjacking. It is noisy in resource terms and often the first sign of an otherwise quiet compromise.","detect":["Sustained high CPU by an unrecognised process, especially on servers","Outbound connections to mining pool ports and domains","New processes running from Temp with high CPU and constant network activity"],"pivots":["Image","DestinationHostname","DestinationPort","ComputerName"],"mits":["M1038","M1037","M1040"],"subs":4,"ref":false,"start":{"win":"Sysmon EID 3 with a mining-pool domain list plus performance telemetry. Cheap to detect and frequently the earliest indicator you get."}},"T1529":{"name":"System Shutdown/Reboot","tactic":"Impact","summary":"Mass shutdowns or reboots deny service and are frequently used to trigger boot-time payloads or to finalise ransomware encryption.","detect":["1074 shutdown initiated with an unexpected process or user, and 6008 unexpected shutdowns","shutdown.exe or Restart-Computer executed across many hosts — score by dc(ComputerName)","Reboots occurring outside patch windows on servers"],"pivots":["Image","CommandLine","Account_Name","ComputerName"],"mits":["M1018","M1026"],"subs":0,"ref":false,"start":{"win":"System log 1074/6008 plus 4688 for shutdown.exe. dc(ComputerName) over a 15-minute window is the differentiator between admin work and an attack."}}};
